<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Snake Game</title>
<style>
*{margin:0;padding:0;box-sizing:border-box}
body{background:#111;overflow:hidden;user-select:none}
canvas{display:block;background:#000}
#game-over{position:fixed;top:50%;left:50%;transform:translate(-50%,-50%) scale(1.5);color:#fff;font-family:monospace;font-size:48px;text-align:center}
#score{position:fixed;top:10px;right:10px;font-family:monospace;font-size:18px}
#menu{position:fixed;top:50%;left:50%;transform:translate(-50%,-50%) scale(1);display:flex;align-items:center;justify-content:center;font-family:monospace;font-size:32px}
#menu button{margin-left:16px;padding:8px 16px;background:#0f3460;color:#fff;border:2px solid #0f3460;border-radius:6px;cursor:pointer}
#menu button:hover{background:#2a5a8a}
#restart{display:none}
</style>
</head>
<body>
<canvas id="gameCanvas" width="600" height="400"></canvas>
<div id="game-over"><div id="msg"></div></div>
<div id="score">Score: 0</div>
<div id="menu"><div id="title"></div><button id="restart">Play Again</button></div>
<script>
const canvas=document.getElementById('gameCanvas'),ctx=canvas.getContext('2d');
const width=canvas.width,height=canvas.height,cell=16,cellSize=cell,speed=12;
let snake,food,deltaX=1,deltaY=0,gameState='playing',score,running;

const init=function(){
  snake=[{x:cell*4,y:cell*3}, {x:cell*2,y:cell*3}, {x:cell*1,y:cell*3}];
  food={x:Math.floor(Math.random()*width/cell)*cell,y:Math.floor(Math.random()*height/cell)*cell};
  score=0;running=true;gameState='playing';
  document.getElementById('game-over').style.display='none';
  document.getElementById('menu').style.display='none';
  document.getElementById('restart').click=restart;
  requestAnimationFrame(loop);
};

const draw=function(){
  ctx.fillStyle='#0f3460';ctx.fillRect(0,0,width,height);
  ctx.fillStyle='#fff';ctx.font='12px monospace';
  for(let i=0;i<snake.length;i++)ctx.fillText(snake[i].x/cell,snake[i].x*cell+cellSize-6,snake[i].y*cell+cellSize-6);
  ctx.fillStyle='#ff4757';ctx.fillRect(food.x,food.y,cell,cell);
};

const update=function(){
  if(!running||gameState!=='playing')return;
  snake.push({x:snake[snake.length-1].x+deltaX,y:snake[snake.length-1].y+deltaY});
  if(snake.length>100)snake.shift();
  if(snake[0].x===food.x&&snake[0].y===food.y){
    score++;document.getElementById('score').textContent='Score: '+score;
    food={x:Math.floor(Math.random()*width/cell)*cell,y:Math.floor(Math.random()*height/cell)*cell};
  }else{
    snake.shift();
  }
  draw();
};

const loop=function(){
  if(running)update();
  requestAnimationFrame(loop);
};

const restart=function(){
  running=false;gameState='over';
  document.getElementById('game-over').style.display='flex';
  document.getElementById('msg').textContent='GAME OVER';
  document.getElementById('msg').style.color='#ff4757';
};

const gameOver=function(){
  running=false;
  ctx.fillStyle='#000';ctx.fillRect(0,0,width,height);
  ctx.fillStyle='#ff4757';ctx.font='bold 72px monospace';
  ctx.textAlign='center';ctx.fillText('GAME OVER',width/2,height/2-40);
  ctx.fillStyle='#fff';ctx.font='48px monospace';
  ctx.fillText('Score: '+score, width/2, height/2+20);
  ctx.fillStyle='#ff4757';ctx.font='20px monospace';
  ctx.fillText('Press Restart to Play Again',width/2, height/2+70);
  requestAnimationFrame(()=>{
    document.getElementById('restart').click();
  });
};

canvas.addEventListener('keydown',e=>{
  if(gameState==='over')return;
  let key='arrow';
  if(e.key==='ArrowUp')key='up';
  else if(e.key==='ArrowDown')key='down';
  else if(e.key==='ArrowLeft')key='left';
  else if(e.key==='ArrowRight')key='right';
  if([key,'up','down','left','right'].includes(key))deltaX=deltaY=0;
  if(e.key===' '||e.key==='Enter')e.preventDefault();
  if(e.key==='ArrowUp'||e.key==='w'||e.key==='w'')deltaY=-1;
  else if(e.key==='ArrowDown'||e.key==='s'||e.key==='s')deltaY=1;
  else if(e.key==='ArrowLeft'||e.key==='a'||e.key==='A')deltaX=-1;
  else if(e.key==='ArrowRight'||e.key==='d'||e.key==='D')deltaX=1;
  else if(e.key===' '||e.key==='Enter')restart();
  if(!['up','down','left','right','w','s','a','d',' ']in e.key)e.preventDefault();
});

canvas.addEventListener('click',()=>{
  if(gameState==='playing')restart();
});

canvas.addEventListener('click',()=>{
  if(gameState!=='playing')gameOver();
  else restart();
});

init();
</script>
</body>
</html>
