<!DOCTYPE html>
<html lang="fr">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Flappy Bird</title>
<style>
*{margin:0;padding:0;box-sizing:border-box}
body{background:#1a1a2e;color:#eee;font-family:'Segoe UI',sans-serif;display:flex;justify-content:center;align-items:center;min-height:100vh}
canvas{border-radius:12px;box-shadow:0 0 20px rgba(255,255,255,.1)}
#overlay{position:absolute;inset:0;background:rgba(0,0,0,.6);display:flex;justify-content:center;align-items:center}
#overlay h1{font-size:48px;margin-bottom:.5em;color:#fff}
#overlay p{font-size:18px;color:#aaa}
#score{position:absolute;bottom:16px;width:100%;text-align:center;font-size:22px;margin:0}
#score b{color:#00ff00}
#game-over{position:absolute;inset:0;background:rgba(0,0,0,.9);display:flex;flex-direction:column;justify-content:center;align-items:center;text-align:center;font-size:48px;color:#ff4444;margin-top:48px}
#game-over button{margin-top:16px;padding:.6em 1.4em;font-size:16px;cursor:pointer}
</style>
</head>
<body>
<canvas id="game"></canvas>
<div id="overlay">
  <h1>FLAPPY BIRD</h1>
  <p>Tap = Jump</p>
</div>
<div id="score">Score: 0</div>
<div id="game-over"></div>
<script>
const canvas=document.getElementById('game');
const ctx=canvas.getContext('2d');
const W=canvas.width=window.innerWidth;
const H=canvas.height=window.innerHeight-20;
canvas.style.width=W+'px';
canvas.style.height=H+'px';

const S=80,SPD=150,GRAV=0.65;
let birdY=H/2, birdVy=0, score=0, gameActive=true, lives=3;

const birds=[
  {x:20, y:H/2, vy:0},
  {x:140, y:H/2, vy:0},
  {x:260, y:H/2, vy:0},
  {x:380, y:H/2, vy:0},
  {x:500, y:H/2, vy:0},
  {x:620, y:H/2, vy:0},
  {x:740, y:H/2, vy:0}
];
const pipes=[
  {x:300, gap:160},
  {x:420, gap:140},
  {x:540, gap:120},
  {x:660, gap:100},
  {x:780, gap:80},
  {x:900, gap:60},
  {x:1020, gap:40}
];

function init(){
  birdY=H/2;birdVy=0;score=0;lives=3;gameActive=true;
  birds.forEach(b=>b.vy=0);
  pipes.forEach(p=>p.x=300+(p.gap+100)*4);
  document.getElementById('game-over').innerHTML='';
  document.getElementById('score').textContent='Score: 0';
  document.getElementById('overlay').style.display='none';
}

function loop(){
  if(!gameActive) return;
  birdVy+=GRAV;
  birdY+=birdVy;
  if(birdY>H*0.65) birdY=H*0.65;

  birds.forEach(b=>{
    b.vy+=0.15;b.x+=SPD-0.035*b.vy*2;
    if(b.x<300+300*30/birds.length){b.x=300+300*30/birds.length;}
  });

  pipes.forEach(p=>{
    p.x-=SPD-0.035*p.vy*2;
    if(p.x+200<p.gap+100*2) p.vy=-0.5;
  });

  if(pipes.some(p=>p.x<100)){
    if(pipes.length>=3){
      pipes.shift();pipes.push({x:300+300*20/pipes.length, gap:160*(pipes.length+1)});
    } else {
      pipes.push({x:300+300*20/pipes.length, gap:160*(pipes.length+1)});
    }
  }

  for(let i=birds.length-1;i>=0;i--){
    if(!gameActive) break;
    if(birds[i].x<200+300*20/pipes.length*0.8){
      birds.splice(i,1);
    }
  }
  if(birds.length<3) birds.push({x:200+300*20/pipes.length*0.8, y:H*0.85, vy:0});

  updateUI();

  if(gameActive){
    requestAnimationFrame(loop);
  }
}

function updateUI(){
  document.getElementById('score').textContent=`Score: ${score}`;
  if(!gameActive && lives<=0){
    gameActive=false;
    document.getElementById('overlay').style.display='flex';
    document.getElementById('overlay h1').textContent='GAME OVER';
    document.getElementById('overlay p').textContent=`Your score: ${score}`;
    document.getElementById('game-over').innerHTML=`<button onclick="init()">Play Again</button>`;
  }
}

function draw(){
  ctx.clearRect(0,0,W,H);
  drawBackground();
  drawBirds();
  drawPipes();
  drawScore();
}

function drawBackground(){
  ctx.fillStyle='#1a1a2e';ctx.fillRect(0,0,W,H);
  ctx.fillStyle='#333';ctx.fillRect(0,0,W,10);
  ctx.fillStyle='#555';ctx.fillRect(0,0,W,15);
  ctx.fillStyle='#888';ctx.fillRect(0,0,W,20);
}

function drawBirds(){
  ctx.fillStyle='#e94560';
  birds.forEach(b=>{
    ctx.beginPath();ctx.arc(b.x,b.y,30,0,Math.PI*2);
    ctx.fill();
  });
}

function drawPipes(){
  pipes.forEach(p=>{
    ctx.fillStyle='#222';
    ctx.fillRect(p.x-5,p.gap+10-5,p.width+10,25);
    ctx.fillStyle='#fff';
    ctx.fillRect(p.x-5,p.gap+10-5,25,p.gap);
  });
}

function drawScore(){
  ctx.fillStyle='#fff';
  ctx.font='bold 24px Monospace';
  ctx.textAlign='left';
  ctx.fillText('Score: ' + score, 10, 28);
}

document.addEventListener('keydown',e=>{
  if(!gameActive) init();
  if(gameActive) {if(e.code==='Space' || e.code==='ArrowUp') e.preventDefault();}
});

canvas.addEventListener('click',()=>{if(gameActive) birdVy=-10;});

init();
loop();
</script>
</body>
</html>
