<!DOCTYPE html>
<html lang="fr">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Flappy Bird</title>
<style>
*{margin:0;padding:0;box-sizing:border-box}
body{background:#0a0a12;color:#c8c8c8;font-family:'Segoe UI',sans-serif;display:flex;justify-content:center;align-items:center;min-height:100vh}
#app{display:grid;grid-template-columns:1fr;gap:16px;background:#141418;border-radius:16px;box-shadow:0 12px 32px rgba(0,0,0,.6)}
#game{padding:32px;background:#0f0f0f;border-radius:16px}
#game h1{font-size:1.4rem;margin-bottom:12px;color:#a0a0a0;text-align:center}
