#game #msg.success{color:#4caf50}
#game #msg.error{color:#f44336}
#game #msg {transition:color .3s}
#game #msg.error {animation:shake .3s}
@keyframes shake{from{transform:translateX(0)}to{transform:translateX(20px)}}
