#game #controls button{padding:10px;border:none;border-radius:8px;background:#2a2a4a;color:#fff;font-size:1rem;cursor:pointer;transition:background .2s}
#game #controls button:hover{background:#3a3a6a}
#game #controls button:disabled{opacity:.4;cursor:not-allowed}
#game #controls button.secondary{background:#16162e}
