</style>
</head>
<body>
<div id="app">
  <div id="game">
    <h1>FLAPPY BIRD</h1>
    <div id="msg">Appuyez pour commencer</div>
    <div id="controls">
      <label><input type="checkbox" id="checkStart"> Montrer les options</label>
      <input type="range" id="difficulty" min="1" max="5" value="3" style="width:100%;accent-color:#4caf50">
      <button id="startBtn">Lancer le jeu</button>
    </div>
    <canvas id="gameCanvas" width="256" height="352"></canvas>
  </div>
  <div id="overlay">
    <h2>FLAPPY BIRD</h2>
    <button id="playBtn">JOUER</button>
    <div class="options">
      <button class="option" data-option="speed">Vitesse ↑</button>
      <button class="option" data-option="gravity">Gravité ↑</button>
      <button class="option" data-option="bouncing">Bouncing ↑</button>
    </div>
  </div>
</div>
<script>
const canvas=document.getElementById('gameCanvas'),ctx=canvas.getContext('2d');
const W=canvas.width,H=canvas.height;
let score=0,height=0,velocity=0,gravity=3.5,bounce=0;
const MAX_SPEED=1.2,MIN_SPEED=0.2;
const KEY={Space:true,Right:true,L:'right',U:'up'};
let paused=false,running=false,gameOver=false;

function reset(){
  score=0;height=0;velocity=0;gravity=3.5;bounce=0;
  paused=false;running=true;gameOver=false;
  document.getElementById('msg').textContent='Appuyez pour commencer';
  document.getElementById('msg').classList.remove('error');
  document.getElementById('msg').classList.remove('success');
  document.getElementById('msg').classList.remove('shake');
  document.getElementById('startBtn').disabled=false;
  document.getElementById('overlay').classList.remove('show');
}

function loop(){
  if(!running||paused)return;
  const dt=Math.min(1/60,1/delta);
  const dt2=Math.min(1/60,1/4);
  if(Math.abs(velocity)>MAX_SPEED)velocity=MAX_SPEED;
  if(velocity<MIN_SPEED)velocity=MIN_SPEED;
  height+=velocity*dt2;
  if(height>H){height=H;velocity=Math.max(velocity,-1.2);}
  if(height<0)height=0;
  velocity+=gravity*dt2;
  if(height<0){height=0;velocity=0;}
  if(height>H-20){height=H-20;velocity=-1.2;}
  draw();
  requestAnimationFrame(loop);
}

function draw(){
  ctx.fillStyle='#0a0a12';
  ctx.fillRect(0,0,W,H);
  ctx.fillStyle='#c8c8c8';
  ctx.fillRect(0,20,W,16);
  if(height>20&&height<H-40){
    ctx.fillStyle='#4caf50';
    ctx.fillRect(0,height-20,256,width);
  }
  ctx.fillStyle='#2a2a4a';
  ctx.fillRect(4,height-10,256,20);
  ctx.fillStyle='#a0a0a0';
  ctx.font='14px Arial';
  ctx.textAlign='left';
  ctx.fillText('Score: '+(score*100),4,18);
  ctx.fillText('Height: '+(height),4,36);
}

function renderOverlay(){
  if(gameOver){
    ctx.fillStyle='#141418';
    ctx.fillRect(0,0,W,H);
    ctx.fillStyle='#fff';
    ctx.font='bold 24px Arial';
    ctx.textAlign='center';
    ctx.fillText('Game Over',W/2,H/2-20);
    ctx.fillStyle='#4caf50';
    ctx.font='16px Arial';
    ctx.textAlign='center';
    ctx.fillText('Score: '+(score*100),W/2,H/2+10);
    ctx.fillStyle='#222';
    ctx.font='12px Arial';
    ctx.fillText('Press Space to restart',W/2,H/2+30);
    ctx.fillStyle='#fff';
    ctx.fillRect(W/2-12,H/2+48,24,8);
    ctx.fillStyle='#4caf50';
    ctx.font='bold 12px Arial';
    ctx.fillText('Play Again',W/2,H/2+64);
    ctx.fillStyle='#2a2a4a';
    ctx.fillRect(W/2-10,H/2+72,20,20);
    ctx.fillStyle='#444';
    ctx.fillRect(W/2-20,H/2+92,40,4);
    ctx.fillStyle='#fff';
    ctx.font='bold 14px Arial';
    ctx.fillText('Play Again',W/2,H/2+104);
  } else {
    ctx.fillStyle='#1a1a2e';
    ctx.fillRect(0,0,W,H);
    ctx.fillStyle='#444';
    ctx.font='18px Arial';
    ctx.textAlign='center';
    ctx.fillText('Space to start',W/2,H/2-20);
    ctx.fillStyle='#fff';
    ctx.font='14px Arial';
    ctx.fillText('Options: '+(document.getElementById('checkStart').checked?', Montrer les options':','),H/2-50);
    ctx.fillStyle='#4caf50';
    ctx.font='12px Arial';
    ctx.textAlign='right';
    ctx.fillText('Vitesse ↑',H/2-30);
    ctx.fillStyle='#2a2a4a';
    ctx.fillRect(H/2-45,360,90,20);
    ctx.fillStyle='#4caf50';
    ctx.fillText('Gravité ↑',H/2-30);
    ctx.fillStyle='#2a2a4a';
    ctx.fillRect(H/2-45,400,90,20);
    ctx.fillStyle='#4caf50';
    ctx.fillText('Bouncing ↑',H/2-30);
    ctx.fillStyle='#2a2a4a';
    ctx.fillRect(H/2-45,440,90,20);
  }
}

function init(){
  document.getElementById('checkStart').checked=false;
  document.getElementById('difficulty').value=3;
  document.getElementById('startBtn').disabled=true;
  document.getElementById('overlay').classList.remove('show');
  reset();
}

function startGame(){
  running=false;paused=false;gameOver=false;
  document.getElementById('msg').textContent='';
  document.getElementById('msg').classList.remove('error');
  document.getElementById('msg').classList.remove('success');
  document.getElementById('msg').classList.remove('shake');
  document.getElementById('startBtn').disabled=true;
  document.getElementById('overlay').classList.add('show');
  renderOverlay();
  requestAnimationFrame(loop);
}

function start(){
  running=true;paused=false;
  document.getElementById('startBtn').disabled=false;
  document.getElementById('overlay').classList.remove('show');
  document.getElementById('msg').textContent='';
  document.getElementById('msg').classList.remove('error');
  document.getElementById('msg').classList.remove('success');
  document.getElementById('msg').classList.remove('shake');
  reset();
  requestAnimationFrame(loop);
}

function stop(){
  running=false;paused=false;gameOver=false;
  document.getElementById('overlay').classList.remove('show');
  document.getElementById('msg').textContent='Appuyez pour commencer';
  document.getElementById('msg').classList.remove('error');
  document.getElementById('msg').classList.remove('success');
  document.getElementById('msg').classList.remove('shake');
  document.getElementById('msg').classList.add('success');
  document.getElementById('startBtn').disabled=false;
}

function handleInput(e){
  if(gameOver){return;}
  if(e.code==='Space'||e.code==='Enter'){start();}
  else if(e.key==='Right'||e.key==='ArrowRight'){if(!running)stop();}
  else if(e.key==='Left'||e.key==='ArrowLeft'){if(!running)stop();}
  else if(e.key==='z'||e.key==='Enter'){document.getElementById('checkStart').checked=!document.getElementById('checkStart').checked;start();}
  else if(e.key==='o'||e.key==='Enter'){document.getElementById('difficulty').value=parseInt(document.getElementById('difficulty').value)+1;start();}
  else if(e.key==='u'||e.key==='ArrowUp'){if(!running)stop();if(!paused){height--;velocity+=gravity;if(velocity>1.2)velocity=1.2;if(velocity<-1.2)velocity=-1.2;}}
  else if(e.key==='w'||e.key==='ArrowDown'){if(!running)stop();}
  else if(e.key==='t'||e.key==='ArrowRightArrowDownArrowLeft'&&running){bounce++;if(bounce>2)bounce=2;}
  else if(e.key==='y'||e.key==='ArrowRightArrowDownArrowLeftArrowLeft'&&running){bounce--;if(bounce<1)bounce=1;}
}

document.addEventListener('keydown',handleInput);
document.getElementById('startBtn').addEventListener('click',start);
document.getElementById('playBtn').addEventListener('click',start);
document.getElementById('difficulty').addEventListener('input',e=>{start();});
document.getElementById('overlay').addEventListener('click',e=>{if(e.target===e.currentTarget)start();});
document.getElementById('checkStart').addEventListener('change',e=>{start();});

init();
</script>
</body>
</html>
