<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Snake Game</title>
<style>
*{margin:0;padding:0;box-sizing:border-box}
body{background:#111;overflow:hidden;display:flex;justify-content:center;align-items:center;height:100vh}
#gameCanvas{display:block;background:#000}
#ui{position:absolute;inset:0;padding:20px;text-align:center;font-family:'Segoe UI',sans-serif;color:#aaa}
#score{font-size:1.2rem;margin-bottom:10px}
#gameOver{position:absolute;inset:0;padding:40px;text-align:center;font-size:1.5rem;color:#f44}
#restartBtn{margin-top:20px;padding:10px 25px;background:#0066cc;color:#fff;border:none;border-radius:4px;cursor:pointer}
</style>
</head>
<body>
<div id="gameCanvas"></div>
<div id="ui">
  <div id="score">Score: 0</div>
</div>
<div id="gameOver">
  <div id="message"></div>
  <button id="restartBtn">Restart Game</button>
</div>
<script>
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');
const scoreEl = document.getElementById('score');
const gameOverEl = document.getElementById('gameOver');
const messageEl = document.getElementById('message');
const restartBtn = document.getElementById('restartBtn');

let canvasW, canvasH, cellSize, snake, direction, nextDirection, score, gameRunning, gameLoop;

function resize() {
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight - 40;
  canvasW = canvas.width;
  canvasH = canvas.height;
  cellSize = Math.min(canvasW, canvasH) / 21;
  if (snake.length > 2) snake[2] = { x: snake[1].x, y: snake[1].y };
}

function init() {
  canvasW = canvas.height = canvas.width = 0;
  canvas.innerHTML = '';
  score = 0;
  scoreEl.textContent = 'Score: 0';
  direction = { x: 1, y: 0 };
  nextDirection = direction;
  score = 0;
  messageEl.textContent = '';
  gameRunning = true;
  gameLoop = requestAnimationFrame(loop);
}

function resetGame() {
  snake = [{ x: canvasW/2, y: canvasH/2 }];
  direction = { x: 1, y: 0 };
  nextDirection = direction;
  score = 0;
  scoreEl.textContent = 'Score: 0';
  messageEl.textContent = '';
  gameRunning = true;
  gameLoop = requestAnimationFrame(loop);
}

function loop() {
  if (!gameRunning) return;
  ctx.clearRect(0, 0, canvasW, canvasH);

  // Draw grid
  ctx.strokeStyle = '#222';
  ctx.lineWidth = 1;
  for (let i = 0; i <= canvasW; i += cellSize) {
    ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i, canvasH); ctx.stroke();
  }
  for (let i = 0; i <= canvasH; i += cellSize) {
    ctx.beginPath(); ctx.moveTo(0, i); ctx.lineTo(canvasW, i); ctx.stroke();
  }

  // Draw snake
  snake.forEach((seg, idx) => {
    ctx.fillStyle = idx === 0 ? '#0f0' : '#222';
    ctx.beginPath();
    ctx.rect(seg.x * cellSize + 1, seg.y * cellSize + 1, cellSize - 2, cellSize - 2);
    ctx.fill();
  });

  // Draw food
  ctx.fillStyle = '#f44';
  ctx.beginPath();
  ctx.arc(snake[0].x * cellSize + cellSize/2, snake[0].y * cellSize + cellSize/2, cellSize * 0.35, 0, Math.PI * 2);
  ctx.fill();

  // Draw score
  ctx.fillStyle = '#fff';
  ctx.font = '12px Segoe UI';
  ctx.textAlign = 'right';
  ctx.fillText(`Score: ${score}`, canvasW - 80, 20);

  // Check collision
  if (snake[0].x === 0 || snake[0].x === canvasW || snake[0].y === 0 || snake[0].y === canvasH) {
    gameRunning = false;
    messageEl.textContent = 'GAME OVER';
    messageEl.style.color = '#f44';
  } else if (snake[0].x === food.x && snake[0].y === food.y) {
    score++;
    scoreEl.textContent = 'Score: ' + score;
    nextDirection = { x: 0, y: 1 };
  } else {
    nextDirection = direction;
  }

  direction = nextDirection;
  snake.unshift({ x: snake[0].x + direction.x, y: snake[0].y + direction.y });

  // Loop
  gameLoop = requestAnimationFrame(loop);
}

canvas.addEventListener('keydown', (e) => {
  if (['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)) {
    e.preventDefault();
    nextDirection = { x: 0, y: 0 };
    if (e.key === 'ArrowUp') nextDirection = { x: 0, y: -1 };
    if (e.key === 'ArrowDown') nextDirection = { x: 0, y: 1 };
    if (e.key === 'ArrowLeft') nextDirection = { x: -1, y: 0 };
    if (e.key === 'ArrowRight') nextDirection = { x: 1, y: 0 };
  }
});

canvas.addEventListener('mousemove', (e) => {
  if (gameRunning) {
    const rect = canvas.getBoundingClientRect();
    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;
    const cx = Math.floor(mouseX / cellSize);
    const cy = Math.floor(mouseY / cellSize);
    if (cx >= 0 && cx < canvasW && cy >= 0 && cy < canvasH) {
      direction = { x: cx - snake[0].x, y: cy - snake[0].y };
    }
  }
});

canvas.addEventListener('click', (e) => {
  if (gameRunning) {
    e.preventDefault();
    resetGame();
  }
});

function loop() {
  if (!gameRunning) return;
  ctx.clearRect(0, 0, canvasW, canvasH);
  draw();
  gameLoop = requestAnimationFrame(loop);
}

function draw() {
  if (snake.length > 2) snake[2] = { x: snake[1].x, y: snake[1].y };
  ctx.fillStyle = '#000';
  ctx.fillRect(0, 0, canvasW, canvasH);
}

canvas.addEventListener('click', resetGame);

window.addEventListener('resize', resize);

init();
</script>
</body>
</html>
