  <div id="message"><span class="text">Game Over</span><span class="text">Click Restart</span></div>
  <button id="restartBtn">Restart</button>
</div>
<script>
const COLS=22, ROWS=22, SIZE=20, SPEED=12, INITIAL_SNAKE=[50,50,10,10], FOOD=[200,200,0];
let snake, food, score, game, lastTick, running, gameOver;

function init() {
  snake=[...INITIAL_SNAKE]; score=0; gameOver=false; running=true;
  document.getElementById('score').textContent=`Score: ${score}`;
  document.getElementById('message').classList.add('hidden');
  document.getElementById('gameContainer').style.background='#161b2b';
  food=[Math.floor(Math.random()*COLS), Math.floor(Math.random()*ROWS)];
  render();
  lastTick=performance.now();
}

function loop() {
  if(!running || gameOver) return;
  const now=performance.now();
  if(now-lastTick>1000/SPEED) {
    lastTick=now;
    move();
    render();
  }
  requestAnimationFrame(loop);
}

function move() {
  if(gameOver) return;
  const dx=[-1,0,1,0], dy=[0,1,0,-1];
  const head=snake[0];
  const idx=(head+1)%COLS;
  const next=[head+dx[idx], head+dy[idx]];
  const nextCol=next[0]%COLS, nextRow=next[1]%ROWS;

  const collision=nextCol===food[0]&&nextRow===food[1];
  if(collision||snake.some(s=>s[0]===next[0]&&s[1]===next[1])) {
    gameOver=true;
    document.getElementById('message').classList.remove('hidden');
    document.getElementById('message').children[0].textContent='Click Restart';
    document.getElementById('message').children[1].textContent='';
  } else {
    snake.unshift(next);
    if(next[0]===food[0]&&next[1]===food[1]) {
      food=[Math.floor(Math.random()*COLS), Math.floor(Math.random()*ROWS)];
      score++;
      document.getElementById('score').textContent=`Score: ${score}`;
    }
  }
}

function render() {
