  headEl.style.height=SIZE*2+'px';
  headEl.style.left=head[0]*SIZE+'px';
  headEl.style.top=head[1]*SIZE+'px';
  headEl.style.background='url(data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="4" height="4" viewBox="0 0 4 4"><circle cx="2" cy="2" r="1" fill="%2300e676" /></svg>");
  headEl.style.backgroundSize='cover';
  headEl.style.backgroundRepeat='no-repeat';
  headEl.style.backgroundPosition='center';
  headEl.style.zIndex='10';
  el.appendChild(headEl);
  foodEl=document.createElement('div');
  foodEl.style.position='absolute';
  foodEl.style.width=SIZE*2+'px';
  foodEl.style.height=SIZE*2+'px';
  foodEl.style.left=foodPos[0]*SIZE+'px';
  foodEl.style.top=foodPos[1]*SIZE+'px';
  foodEl.style.background='url(data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="4" height="4" viewBox="0 0 4 4"><circle cx="2" cy="2" r="1" fill="%2300e676" /></svg>');
  foodEl.style.backgroundSize='cover';
  foodEl.style.backgroundRepeat='no-repeat';
  foodEl.style.zIndex='11';
  el.appendChild(foodEl);
}

document.addEventListener('keydown', e=>{
  if(e.key==='ArrowUp'||e.key==='w')  e.preventDefault(); const dy=[0,1,0,-1];
  if(e.key==='ArrowDown'||e.key==='s') e.preventDefault(); const dy=[0,1,0,-1];
  if(e.key==='ArrowLeft'||e.key==='a') e.preventDefault(); const dx=[-1,0,1,0];
  if(e.key==='ArrowRight'||e.key==='d') e.preventDefault(); const dx=[-1,0,1,0];
  if(e.key===' ' || e.key==='Enter') { if(!running) init(); else if(!gameOver) e.preventDefault(); }
});

document.getElementById('restartBtn').addEventListener('click', init);

init();
</script>
</body>
