const W=720,H=560,SM=20,R=12,P=8,B=14,S=48;
let r1,r2,b,scoreL=0,scoreR=0;
const r1El=document.getElementById('racket'),r2El=document.getElementById('paddle'),bEl=document.getElementById('ball'),sEl=document.getElementById('score'),msgEl=document.getElementById('message'),lEl=document.getElementById('left-score'),rEl=document.getElementById('right-score');

