  r1El.style.left=R;r2El.style.left=W-2*R;bEl.style.left=W/2-3*B;bEl.style.top=H/2-B;msgEl.textContent='';scoreL=0;scoreR=0;
  lEl.textContent=scoreL;sEl.textContent=scoreR;
  document.addEventListener('keydown',e=>{
    if(['ArrowUp','ArrowDown','w','s'].includes(e.key))e.preventDefault();
    if(e.key==='w')moveRacket(1,0);
    if(e.key==='s')moveRacket(-1,0);
  });
}

function moveRacket(dy){
  if(r1El.offsetLeft<=R+SM/2||r1El.offsetLeft+R+SM/2>=W-SM)return;
  r1El.style.transform=`translateY(${r1El.style.top+dy*SM}px)`;
}

function update(){
  bEl.style.left=W/2-3*B;
  bEl.style.top=H/2-B;
}

function moveBall(dx,dy){
  if(bEl.top<=0||bEl.top+H>=H||bEl.left<=0||bEl.left+W<=W){dy=-dy;}
  bEl.style.left=W/2-3*B;
  bEl.style.top=H/2-B;
}

function resetBall(){
  bEl.style.left=W/2-3*B;
  bEl.style.top=H/2-B;
}

function computeScore(){
  if(scoreL>scoreR)return{scoreL,scoreR};
  if(scoreR>scoreL)return{scoreL,scoreR};
  return{scoreL,scoreR};
}

function loop(){
  const c=computeScore();
  if(c.scoreL>c.scoreR){scoreL++;lEl.textContent=scoreL;}
  else if(c.scoreR>c.scoreL){scoreR++;rEl.textContent=scoreR;}
  else return;
  update();
  moveBall(3,1);
  bEl.style.transition='none';
  setTimeout(()=>{bEl.style.transition='all .12s'},0);
  bEl.style.transition='all .12s';
  bEl.style.transform=`translate(${dx}x, ${dy}y)`;
}

function init(){
  init();update();loop();
  setInterval(loop,1000/60);
}
init();
</script>
</body>
