<!DOCTYPE html>
<html lang="fr">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Pong</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body { background: #0a0a12; display: flex; flex-direction: column; align-items: center; justify-content: center; height: 100vh; overflow: hidden; }
  #ui { display: flex; gap: 20px; margin-bottom: 15px; font-family: 'Segoe UI', sans-serif; color: #a0a0b0; font-size: 1.2rem; }
  #ui div { background: #1a1a2e; padding: 5px 12px; border-radius: 20px; }
  #game { position: relative; height: 400px; border-radius: 50%; box-shadow: 0 0 40px rgba(255,255,255,0.1); }
  .ball { position: absolute; border-radius: 1px; }
  #racketL, #racketR { width: 15px; height: 100px; background: #000; border: 2px solid #000; border-radius: 2px; position: absolute; cursor: pointer; }
  #racketL { top: 200px; left: 20px; }
  #racketR { bottom: 200px; right: 20px; }
  #score { font-weight: bold; color: #ffffff; text-shadow: 0 0 10px #000; }
</style>
</head>
<body>
<div id="ui"><div id="scoreL">Joueur: 0</div><div id="scoreR">PC: 0</div></div>
<div id="game">
  <div id="racketL"></div>
  <div id="racketR"></div>
  <div class="ball"></div>
</div>
<script>
const R = 14, H = 400, W = 800;
let x, y, vx, vy;
let scoreL = 0, scoreR = 0;
let gameOn = false;

function init() {
  x = W / 2;
  y = H / 2;
  vx = 4;
  vy = 4;
  scoreL = 0;
  scoreR = 0;
  gameOn = true;
  updateUI();
}

function updateUI() {
  document.getElementById('scoreL').textContent = `Joueur: ${scoreL}`;
  document.getElementById('scoreR').textContent = `PC: ${scoreR}`;
}

function reset() {
  gameOn = false;
  x = y = vx = vy = 0;
  scoreL = scoreR = 0;
  updateUI();
}

function draw() {
  ctx.clearRect(0, 0, W, H);
  const r = R + 10;

  // Ball
  ctx.beginPath();
  ctx.arc(x, y, r, 0, Math.PI * 2);
  ctx.fillStyle = '#000';
  ctx.fill();
  ctx.strokeStyle = '#0f0';
  ctx.lineWidth = 2;
  ctx.stroke();

  // Racket L
  ctx.fillStyle = '#000';
  ctx.fillRect(x - r, H - 2 * r, 2 * r, 20);

  // Racket R
  ctx.fillStyle = '#000';
  ctx.fillRect(x + r, H - 2 * r, 2 * r, 20);

  // Ball trajectory lines
  const cx = x + vx * r;
  const cy = y + vy * r;
  if (cx > W + r) {
    scoreR++;
    reset();
  } else if (cx < r) {
    scoreL++;
    reset();
  }
}

function loop() {
  if (!gameOn) return;

  y += vy;
  x += vx;

  // Ball bounce off top/bottom
  if (y - r < 0 || y + r > H) {
    vy = -vy;
  }

  // Ball bounce off rackets
  if (y + r >= H - 20 && Math.abs(vx) > 1) {
    vy = -vy;
  }
  if (y - r <= 20 && Math.abs(vx) > 1) {
    vy = -vy;
  }
  if (Math.abs(x - (W - 20)) < 20 && Math.abs(vy) > 1) {
    vy = -vy;
  }
  if (Math.abs(x + 20) < 20 && Math.abs(vy) > 1) {
    vy = -vy;
  }

  draw();
  requestAnimationFrame(loop);
}

document.getElementById('racketL').addEventListener('click', () => {
  if (gameOn) {
    if (vy < 0) vy += 1.5;
    else vy += 1;
    vy *= 0.95;
  }
});

document.getElementById('racketR').addEventListener('click', () => {
  if (gameOn) {
    if (vy > 0) vy -= 1.5;
    else vy -= 1;
    vy *= 0.95;
  }
});

document.addEventListener('keydown', (e) => {
  if (!gameOn) return;
  if (e.code === 'ArrowUp' || e.code === 'w') { vy += 2; vy *= 0.95; }
  else if (e.code === 'ArrowDown' || e.code === 's') { vy -= 2; vy *= 0.95; }
  else if (e.code === 'Space' || e.key === ' ') { vy += 3; vy *= 0.9; }
});

const ctx = document.getElementById('game').getContext('2d');
init();
requestAnimationFrame(loop);
</script>
</body>
</html>
