</div>
<div id="overlay">
  <h1>GAME OVER</h1>
  <p>Final Score: 0</p>
  <button id="restartBtn">Play Again</button>
</div>
<canvas id="gameCanvas"></canvas>
<script>
const canvas=document.getElementById('gameCanvas'),ctx=canvas.getContext('2d');
const canvasW=canvas.width,canvasH=canvas.height;
let paddleW=canvasW*0.8,paddleH=canvasH*0.15,brickW=40,brickH=14,bricks=20;
let score=0,lives=3,bricksLeft=bricks,gameState='playing',gameOver=false;
const bricks=[];
const colors=['#e74c3c','#2ecc71','#3498db','#9b59b6','#f1c40f'];
const brickRows=5,brickCols=4,spacing=6;
function initBricks(){
  bricks=[];
  const cols=brickCols,rows=brickRows,startY=canvasH*0.35;
  for(let c=0;c<cols;c++){
    for(let r=0;r<rows;r++){
      const x=c*brickW+spacing*(c+1),y=startY+r*brickH;
      bricks.push({x,y,w:brickW,h:brickH,color:colors[r%6]});
    }
  }
}
function build(){
  ctx.fillStyle='#1a1a1a';ctx.fillRect(0,0,canvasW,canvasH);
  ctx.fillStyle='#2a2a2a';ctx.fillRect(0,canvasH-20,canvasW,20);
  ctx.fillStyle='#444';ctx.fillRect(0,canvasH-22,canvasW,4);
  ctx.fillStyle='#555';ctx.fillRect(0,canvasH-26,canvasW,6);
  ctx.fillStyle='#333';ctx.fillRect(0,canvasH-30,canvasW,12);
  ctx.fillStyle='#333';ctx.fillRect(canvasW-24,canvasH-20,4,12);
  for(const b of bricks){
