  paddleW=Math.min(paddleW,canvasW);
  if(gameState==='playing'){
    const dx=0,keys={arrows:false,space:false};
    const e=event||null;
    if(e){if(e.type==='keydown'){if(e.code==='ArrowUp'||e.code==='ArrowDown'||e.code==='Space'){keys[e.code]=true;}if(e.key==='w'||e.key==='W'||e.key==='ArrowUp')keys['ArrowUp']=true;if(e.key==='s'||e.key==='S'||e.key==='ArrowDown')keys['ArrowDown']=true;}}if(keys['ArrowLeft'])dx=-1;if(keys['ArrowRight'])dx=1;if(keys['space']){dx=0.5;if(lives<=0){lives=3;gameState='win';updateScore();build();}else{gameState='playing';}}
    paddleW+=dx;if(paddleW<0)paddleW=canvasW;if(paddleW>canvasW)paddleW=0;
    ctx.fillStyle='#0f0';ctx.fillRect(paddleW,paddleY,paddleW,paddleH);
  }
  if(gameState==='win'){
    const y=canvasH*0.45,px=canvasW*0.25,py=canvasH*0.65;
    ctx.fillStyle='#0f0';ctx.fillRect(px,y,canvasW-px-2,py-2);
    ctx.fillStyle='#ff6b35';ctx.font='bold 48px monospace';ctx.textAlign='center';ctx.fillText(score,px+(canvasW-px)/2,py+(py-2)/2);
    ctx.fillStyle='#ff6b35';ctx.font='bold 24px monospace';ctx.fillText(`Lives: ${lives}`,px+(canvasW-px)/2,py+36);
    ctx.fillStyle='#ff6b35';ctx.textAlign='left';ctx.fillText(`Score: ${score}`,px+4,py+60);
    if(lives<=0){
      gameState='lose';
      gameOver=true;
    }
  }
}
function drawBricks(){
  for(const b of bricks){
    ctx.fillStyle=b.color;ctx.fillRect(b.x,b.y,b.w,b.h);
    ctx.strokeStyle='#444';ctx.strokeRect(b.x+0.5,b.y+0.5,b.w-1,b.h-1);
  }
}
function draw() {
  ctx.clearRect(0,0,canvasW,canvasH);
  build();drawBricks();
  if(gameState==='playing'){
    update();
    ctx.fillStyle='#0f0';ctx.fillRect(paddleW,paddleY,paddleW,paddleH);
    if(lives<=0){
      gameState='lose';
      gameOver=true;
    }
  }
  if(gameState==='win'){
    draw();
  }
}
function gameLoop(){
  if(gameState==='playing')update();draw();
  requestAnimationFrame(gameLoop);
}
canvas.addEventListener('click',()=>{
  if(gameState!=='play')gameState='play';
  paddleY=Math.min(paddleY+20,canvasH-paddleH);
});
canvas.addEventListener('keydown',e=>{
  if(gameState==='playing'||gameState==='win'){
    e.preventDefault();
    if(e.code==='Space')lives--;
    if(e.key==='r'||e.key==='R')reset();
  }
});
canvas.addEventListener('mousemove',e=>{
  if(gameState!=='play')return;
  const rect=canvas.getBoundingClientRect();
  paddleY=Math.min(Math.max(rect.bottom-paddleH,0),canvas.height-paddleH);
});
function reset(){
  score=0;lives=3;bricksLeft=bricks;
  gameState='playing';
  build();draw();
}
canvas.addEventListener('click',reset);
canvas.addEventListener('click',()=>{
  if(gameState==='play')gameState='win';
  paddleY=Math.min(paddleY+20,canvasH-paddleH);
  if(lives<=0){lives=3;gameState='playing';updateScore();build();draw();}
});
canvas.addEventListener('click',()=>{
  if(gameState==='play')gameState='win';
