<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Breakout</title>
<style>
*{margin:0;padding:0;box-sizing:border-box}
body{background:#111,color:#eee;font-family:'Segoe UI',system-ui,sans-serif;display:flex;justify-content:center;align-items:center;min-height:100vh;user-select:none}
canvas{border:1px solid #444;border-radius:4px}
#overlay{position:absolute;inset:0;display:flex;flex-direction:column;justify-content:center;align-items:center;cursor:pointer;opacity:0;transition:opacity .2s}
#overlay.show{opacity:1}
#overlay h1{font-size:48px;margin-bottom:12px}
#overlay h2{font-size:24px;margin-bottom:20px}
