#lives{font-size:22px;color:#ff5555}
#winMsg{font-size:32px;color:#0f0;color:#0f0;margin:20px 0}
#loseMsg{font-size:32px;color:#ff5555}
</style>
</head>
<body>
<canvas id="c"></canvas>
<div id="overlay"><div id="msg">Press Space to restart</div><button id="restart">Play Again</button></div>
<div id="ui"><div id="score">Score: <b id="sVal">0</b></div><div id="lives">Lives: <b id="lVal">3</b></div></div>
<script>
const canvas=document.getElementById('c'),ctx=canvas.getContext('2d');
const W=canvas.width=720,H=canvas.height=450;
const P=W/2-50,P_W=100,P_H=25;
const B=30,B_W=90,B_H=20,B_R=6,C_W=7,C_H=30;

const PADDLE_SPEED=6;
const BALL_SPEED=4;
const BALL_RADIUS=14;
const BRICK_COLS=8,BRICK_ROWS=6;
const BRICK_COLS_W=90,BRICK_ROWS_H=30;
const BRICK_COLS_SP=B_W+20,BRICK_ROWS_SP=20;

const scoreEl=document.getElementById('sVal'),livesEl=document.getElementById('lVal');

let paddle,Y,P;
let bricks=[],score=0,lives=3,gameOver=false,win=false;

function init(){
  paddle={x:P_P, y:H-30, w:P_W, h:P_H };
  bricks=[]; for(let r=0;r<BRICK_ROWS;r++) for(let c=0;c<BRICK_COLS;c++){
    if((r+1)*(c+1)%4!==0){ bricks.push({x:(c+1)*(BRICK_COLS_W+BRICK_COLS_SP), y:(r+1)*(BRICK_ROWS_H+BRICK_ROWS_SP), w:BRICK_COLS, h:BRICK_ROWS_H+BRICK_ROWS_SP, r,c}) };
  }
}

function draw(){
  ctx.clearRect(0,0,W,H);
  if(gameOver){ ctx.fillStyle='#000'; ctx.font='bold 48px monospace'; ctx.textAlign='center'; ctx.fillText(win?'WON':'LOST',W/2,H/2+22); ctx.fillStyle='#fff'; ctx.font='40px monospace'; ctx.fillText('Press Space to restart',W/2,H/2+60); return; }
  if(win) { ctx.fillStyle='#0f0'; ctx.fillRect(0,0,W,H); ctx.fillStyle='#fff'; ctx.font='bold 36px monospace'; ctx.textAlign='center'; ctx.fillText('WIN!',W/2,H/2+30); }

  // Bricks
  for(let i=0;i<bricks.length;i++){
    let b=bricks[i]; let c=ctx.createLinearGradient(b.x,b.y,b.x+b.w,b.y+b.h);
    c.addColorStop(0,#e0e0e0); c.addColorStop(1,#ff5555);
    ctx.fillRect(b.x,b.y,b.w,b.h);
    ctx.fillStyle='rgba(0,0,0,.1)'; ctx.fillRect(b.x-1,b.y-1,b.w+2,b.h+2);
  }

  // Paddle
  ctx.fillStyle='#0f0'; ctx.fillRect(paddle.x,paddle.y,paddle.w,paddle.h);
  ctx.strokeStyle='#0f0'; ctx.strokeRect(paddle.x,paddle.y,paddle.w,paddle.h);

  // Ball
  let gx=10,gy=10;
  if(Math.random()<.5) gx=-gx;
  if(Math.random()<.5) gy=-gy;
  ctx.beginPath(); ctx.arc(W/2+gx,H/2+gy,BALL_RADIUS,0,Math.PI*2); ctx.fillStyle='#0f0'; ctx.fill(); ctx.strokeStyle='#fff'; ctx.stroke();
  ctx.fillStyle='#fff'; ctx.font='bold 14px monospace'; ctx.textAlign='center'; ctx.fillText('100',W/2+gx*5,H/2+gy*5);
  ctx.fillStyle='#0f0'; ctx.fillRect(W/2+gx-4,H/2+gy-4,BALL_RADIUS*2,BALL_RADIUS*2);

  // Score/Lives
  ctx.fillStyle='#fff'; ctx.font='bold 20px monospace'; ctx.fillText('Score:'+score,'W',10,10);
  ctx.fillStyle='#ff5555'; ctx.font='bold 20px monospace'; ctx.fillText('Lives:'+lives,'E',10,H-20);
}

function update(){
  if(gameOver)return;

  let dx=0,dy=0;
  if(PADDLE_SPEED*10>0)dx=sign(PADDLE_SPEED);
  else if(PADDLE_SPEED*10<0)dx=-sign(PADDLE_SPEED);
  else dx=0;

  if(wheelDelta!==0)dy=-wheelDelta*20;

  paddle.x+=dx;
  if(paddle.x<P_W) paddle.x=P_W; if(paddle.x<0) paddle.x=0;

  let dx2=0,dy2=0;
  if(Math.abs(dy)>0.5)dx2=sign(dy); else if(dy>0)dx2=1; else dx2=-1;

  let mx=W-P_W-10,my=H-30,mx2=B-30;
  let bX=bricks.length?bricks[bricks.length-1].x:0, bY=bricks.length?bricks[bricks.length-1].y:0;
  let bW=bricks.length?bricks[bricks.length-1].w:0, bH=bricks.length?bricks[bricks.length-1].h:0;

  for(let i=bricks.length-1;i>=0;i--){
    let b=bricks[i]; let r=b.r,c=b.c;
    if(bX>mx2){ mx2-=bW; r--; if(r<0) bricks.splice(i,1); }
    if(bY>bH){ bY-=bH; c--; if(c<0) bricks.splice(i,1); }
    if(bY>bH+bH){ bY-=bH; r--; if(r<0) bricks.splice(i,1); }
    if(bY>H-30-bH) dy2+=bH; else if(bY<30-bH) dy2-=bH;
    if(bY+dy2>bH) dy2+=2; if(bY+dy2>H-30-bH) dy2-=2;
    let tx=Math.max(0,Math.min(W-bW,mx)); let ty=Math.max(0,bH),tx2=Math.max(0,Math.min(W-bW,bX+bW)); if(tx>tx2&&tx>0){ mx=tx; mx2=tx2; } if(ty>bH){ bY=bH; r++; if(r<0) bricks.splice(i,1); }
    if(bY+dy2>bH){ bY=bH; r++; if(r<0) bricks.splice(i,1); }
  }

  if((mx>=paddle.x&&mx<=paddle.x+paddle.w)&&dy>0){
    if(dy>0)dy=-.15; else dy=-.15;
    for(let i=bricks.length-1;i>=0;i--){
      let b=bricks[i]; if(b.r===bX+bW&&b.c===bY-bH){ bX-=bW; bY+=bH; score+=b.r*20+b.c*20; break; }
    }
  }

  let bx=mx-bX-30,by=my-bY-30;
  if(Math.sqrt(bx*bx+by*by)<BALL_RADIUS*2){ dy2=-dy2; let c=sign(bx)+sign(by); bx*=c; by*=c; if(bx<0&&by<0)bx*=2; if(by<0&&bx<0)by*=2; dx2=sign(bx)+sign(by); }
  else if(Math.abs(bx)>30) dx2=sign(bx); else if(bx>0)dx2=1; else dx2=-1;
  let speed=Math.sqrt(dx2*dx2+dy2*dy2);
  dx2/=speed; dy2/=speed;
  for(let i=bricks.length-1;i>=0;i--){
    let b=bricks[i]; b.x+=dx2*speed; b.y+=dy2*speed;
    if(b.x<0||b.x>B-bW||b.y<0||b.y>bH+bH){ bX+=bW; bY+=bH; }
  }
}

function sign(x){ return x>0?1:-1<0?-1:0; }

function loop(){
  if(!gameOver){ update(); draw(); requestAnimationFrame(loop); }
  else if(win){ score+=200; lives=30; init(); }
  else if(lives<3){ lives--; init(); }
  else gameOver=true; score+=0; lives=0; init();
}

function resetBricks(){
  for(let r=0;r<BRICK_ROWS;r++) for(let c=0;c<BRICK_COLS;c++){
    if((r+1)*(c+1)%4!==0){ bricks.push({x:(c+1)*(BRICK_COLS_W+BRICK_COLS_SP), y:(r+1)*(BRICK_ROWS_H+BRICK_ROWS_SP), w:BRICK_COLS, h:BRICK_ROWS_H+BRICK_ROWS_SP, r,c}) };
  }
}

function handleKey(){
  document.addEventListener('keydown',e=>{
    if(gameOver){ if(e.code==='Space'&&e.keyCode===32){ e.preventDefault(); init(); } return; }
    if(e.code==='Space'){ e.preventDefault(); init(); }
    if(e.key==='ArrowLeft'||e.key==='a'){ e.preventDefault(); P-=PADDLE_SPEED; if(P<=0)P=0; }
    if(e.key==='ArrowRight'||e.key==='d'){ e.preventDefault(); P+=PADDLE_SPEED; if(P>=W-P_W-10)P=W-P_W-10; }
    if(e.key==='w'||e.key==='ArrowUp'){ e.preventDefault(); Y-=PADDLE_SPEED; if(Y<=0)Y=0; }
    if(e.key==='s'||e.key==='ArrowDown'){ e.preventDefault(); Y+=PADDLE_SPEED; if(Y>=H-30-30)Y=H-30-30; }
    if(e.key===' '){ e.preventDefault(); init(); }
    if(e.key==='w'||e.key==='ArrowUp')wheelDelta=-5;
    if(e.key==='s'||e.key==='ArrowDown')wheelDelta=5;
  });
}

function restart(){
  init(); loop();
}

function init(){ P=0; Y=H/2; resetBricks(); score=0; lives=3; gameOver=false; win=false; document.getElementById('restart').innerHTML='Play Again'; document.getElementById('restart').onclick=restart; document.getElementById('overlay').classList.add('show'); document.getElementById('overlay').classList.remove('hide'); scoreEl.textContent=score; livesEl.textContent=lives; }
document.addEventListener('touchstart',e=>{ e.preventDefault(); init(); });
document.addEventListener('mousedown',e=>{ e.preventDefault(); init(); });
document.addEventListener('wheel',e=>{ e.preventDefault(); wheelDelta=-(e.deltaY||e.detail)||e.deltaY; }, {passive:false});
init();
</script>
</body>
</html>
