<body>
<div id="game">
  <div class="card" data-c1="a" data-c2="b" data-c3="c" data-c4="d" tabindex="0" role="button" tabindex="0"></div>
  <div class="card" data-c1="a" data-c2="b" data-c3="c" data-c4="d" tabindex="0" role="button" tabindex="0"></div>
  <div class="card" data-c1="a" data-c2="b" data-c3="c" data-c4="d" tabindex="0" role="button" tabindex="0"></div>
  <div class="card" data-c1="a" data-c2="b" data-c3="c" data-c4="d" tabindex="0" role="button" tabindex="0"></div>
