<button id="replay">Rejouer</button>
<script>
const CARD_COUNT = 16;
let flipped = 0, matches = 0, gameActive = false;

function loadCards() {
  const a = document.querySelector('[data-c1="a"]'), b = document.querySelector('[data-c1="b"]'),
    c = document.querySelector('[data-c1="c"]'), d = document.querySelector('[data-c1="d"]');
  const cards = [a, b, c, d, a, b, c, d, a, b, c, d, a, b, c, d];
  cards.forEach((c, i) => {
    c.dataset.value = i + 1;
    c.dataset.index = i;
  });
  document.querySelectorAll('.card').forEach((card, i) => card.dataset.index = i);
}

function init() {
  loadCards();
  document.querySelectorAll('.card').forEach(card => {
    card.addEventListener('click', () => flipCard(card));
    card.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') flipCard(card);
    });
  });
  document.getElementById('message').textContent = 'Cliquez pour commencer';
  gameActive = true;
  flipped = 0;
  matches = 0;
  document.getElementById('replay').disabled = true;
  document.getElementById('message').style.color = '#00ffab';
}

function flipCard(card) {
  if (!gameActive) return;
  if (card.classList.contains('flipped')) return;
  card.classList.add('flipped');
  flipped++;
  document.getElementById('message').textContent = `Coups : ${flipped}/${CARD_COUNT}`;
  if (flipped === 1) {
    document.getElementById('message').style.color = '#00ffab';
  } else if (flipped === CARD_COUNT / 2) {
    document.getElementById('message').style.color = '#e67e22';
  }
  if (flipped === CARD_COUNT / 2) {
    checkForMatches();
  }
}

function checkForMatches() {
  let first = null, second = null;
  document.querySelectorAll('.card.flipped').forEach(card => {
    if (!first && !second) { first = card; }
    else if (first && !second) { second = card; }
    else if (first && second) { matches++; first.classList.add('flipped'); second.classList.add('flipped'); }
    first = null;
    second = null;
  });
  if (matches === CARD_COUNT / 2) {
    document.getElementById('message').textContent = 'Victoire !';
    document.getElementById('message').style.color = '#00e676';
    gameActive = false;
    document.getElementById('replay').disabled = false;
    flipped = 0;
  }
}

document.getElementById('replay').addEventListener('click', init);

document.addEventListener('keydown', (e) => {
  if (e.key === 'Escape') e.preventDefault();
});

init();
</script>
</body>
</html>
