.card[data-value].matched{filter:brightness(0);opacity:0}
#msg{font-size:1.2rem;margin-top:16px;color:#e94560;text-align:center}
#cmd{margin-top:12px;font-size:.95rem;padding:10px 24px;background:#e94560;color:#fff;border:none;border-radius:8px;cursor:pointer;transition:background .2s}
#cmd:hover{background:#c53046}
</style>
</head>
<body>
<h1>Memory</h1>
<div id="game"></div>
<div id="msg"></div>
<button id="cmd">Rejouer</button>
<script>
const R=4, C=4, S=R*C;
const colors=['#4a9eff','#5bd5ff','#84c7ff','#ffd699','#e2d5ff','#ff9a8d','#8d8cff','#ff6b81'];
let cards=[], state=0, matched=0;

function init() {
  cards=[];
  let v=0;
  for(let r=0;r<R;r++)for(let c=0;c<C;c++)cards.push({r,c,val:v++});
  for(let i=0;i<S;i++)cards.push({r:i%R, c:Math.floor(i/R)});
  render();
}

function render() {
  const g=document.getElementById('game'), m=document.getElementById('msg'), c=document.getElementById('cmd');
  g.innerHTML='';
  cards.forEach((c,i)=>{
    const d=document.createElement('div');
    d.className='card' + (state==i?' flipped':'');
    d.dataset.i=i;
    d.dataset.val=c.val;
    d.innerHTML=`<div style="width:100%;height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center">`+
                  `<span style="font-size:2rem;font-weight:bold;transition:transform .2s;"><?=c.val}</span></div>`;
    d.addEventListener('click',()=>handleClick(c));
    g.appendChild(d);
  });
}

function handleClick(c) {
  if(state===i||matched>0)return;
  if(c.matched)return;
  c.matched=true;
  c.val=0;
  c.flipped=true;
  matched++;
  if(matched===S/2){msg('Victoire !');state=2;matched=0;}
  else{msg('');state=0;}
  render();
}

function msg(txt){m.textContent=txt;c.disabled=false;}
document.getElementById('cmd').addEventListener('click',()=>{init();});
init();
</script>
</body>
