#restart:hover{background:#c03a55}
</style>
</head>
<body>
<div id="app">
  <h1>Memory</h1>
  <div id="score">Coup(s) : <span id="current">0</span></div>
  <div id="turn">Tour de <b id="playerName"></b></div>
  <div id="grid"></div>
  <div id="message"></div>
  <button id="restart">Rejouer</button>
</div>
<script>
const GRID=4, CARDS=8, MATCH=2, TOTAL=CARDS*2, TILE=72, GAP=6;
const $=id=>document.getElementById(id);
const scoreEl=$('current'), turnEl=$('playerName'), msgEl=$('message'), restart=$('restart');
let cards=Array(TOTAL).fill(0).map(()=>Math.floor(Math.random()*2), 1);
let shuffled=cards.slice().sort(()=>Math.random()-.5);
let selected=0, flipped=0, lastClicked=0;

function init() {
  shuffled.forEach((c,i)=>{
    const card=document.createElement('div');
    card.className='card';
    card.dataset.value=c;
    card.addEventListener('click',()=>onClick(card,i));
    $('grid').appendChild(card);
  });
  scoreEl.textContent=0;
  turnEl.textContent='Tour de';
  msgEl.textContent='';
  document.querySelectorAll('.card').forEach(c=>c.classList.remove('selected'));
  lastClicked=0;
  flipped=0;
}

function onClick(card, idx) {
  if (lastClicked===0 && flipped===0) {
    card.classList.add('selected');
    lastClicked=idx;
  } else if (lastClicked===idx && flipped===0) {
    card.classList.add('flipped');
    flipped=1;
  } else if (flipped===1 && lastClicked===idx) {
    card.classList.remove('flipped');
    flipped=0;
    if (shuffled[idx] === shuffled[idx+1]) {
      flipped=0;
      scoreEl.textContent=Number(scoreEl.textContent)+2;
      msgEl.textContent=`${shuffled[idx]}...`;
      msgEl.style.color='green';
      msgEl.style.fontWeight='bold';
      card.classList.add('selected');
    } else {
      card.classList.add('selected');
      card.classList.add('flipped');
      lastClicked=0;
      flipped=0;
    }
  }
  lastClicked=0;
  if (flipped===1 && lastClicked===0) {
    turnEl.textContent='Votre tour';
  }
  if (shuffled.length===TOTAL) {
    turnEl.textContent='Vainqueur !';
    msgEl.textContent='C'est gagné ! 🎉';
    msgEl.style.color='gold';
    restart.style.background='#e94560';
    restart.style.color='#fff';
  }
}

function reset() {
  cards=Array(TOTAL).fill(0).map(()=>Math.floor(Math.random()*2), 1);
  shuffled=cards.slice().sort(()=>Math.random()-.5);
  selected=0; flipped=0; lastClicked=0;
  $('score').textContent=0;
  turnEl.textContent='Tour de';
  msgEl.textContent='';
  document.querySelectorAll('.card').forEach(c=>c.classList.remove('selected'));
  document.querySelectorAll('.card.flipped').forEach(c=>c.classList.remove('flipped'));
  $('grid').innerHTML='';
  init();
}

restart.addEventListener('click', reset);
init();
</script>
</body>
</html>
