<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Tic Tac Toe</title>
<style>
  body { background:#1a1a2e; color:#eee; display:flex; justify-content:center; align-items:center; height:100vh; margin:0; }
  #game { display:flex; gap:8px; flex-wrap:wrap; }
  .box { width:60px; height:60px; border:2px solid #fff; background:#222; display:flex; justify-content:center; align-items:center; cursor:pointer; font-size:2rem; transition:all .1s; }
  .box:hover { border-color:#ff4444; box-shadow:0 0 12px #ff4444; }
  .box.disabled { opacity:0.2; cursor:not-allowed; }
  #status { margin-top:12px; font-weight:bold; text-align:center; }
  #restart { margin-top:16px; padding:8px 20px; background:#444; color:#fff; border:none; cursor:pointer; border-radius:4px; }
</style>
</head>
<body>
<div id="game"></div>
<div id="status"></div>
<button id="restart">Restart</button>
<script>
const BOARD_SIZE = 3;
const boxes = document.querySelectorAll('.box');
const statusEl = document.getElementById('status');
const restartBtn = document.getElementById('restart');

let board = Array(BOARD_SIZE * BOARD_SIZE).fill(null);
let currentPlayer = 'X';
let gameOver = false;

function init() {
  boxes.forEach(b => {
    b.addEventListener('click', () => handleClick(b));
  });
  restartBtn.addEventListener('click', init);
  render();
}

function handleClick(box) {
  if (gameOver) return;

  if (!board[box.dataset.idx]) {
    board[box.dataset.idx] = currentPlayer;
    render();
    checkWin();
    if (!gameOver) {
      currentPlayer = currentPlayer === 'X' ? 'O' : 'X';
      statusEl.textContent = `Player ${currentPlayer}'s turn`;
    }
  }
}

function render() {
  statusEl.textContent = `Player ${currentPlayer}'s turn`;
  boxes.forEach(box => {
    box.textContent = board[box.dataset.idx] || '';
    box.classList.toggle('disabled', !board[box.dataset.idx]);
  });
}

function checkWin() {
  const lines = [
    [0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,6,12],[3,7,13],[6,8,14]
  ];
  for (const line of lines) {
    if (board[line[0]] && board[line[0]] === board[line[1]] && board[line[1]] === board[line[2]]) {
      gameOver = true;
      statusEl.textContent = `Player ${board[line[0]]} wins! 🎉`;
      return;
    }
  }
  if (!board.some(cell => cell)) {
    gameOver = true;
    statusEl.textContent = "It's a draw! 🤝";
  }
}

function reset() {
  board = Array(BOARD_SIZE * BOARD_SIZE).fill(null);
  currentPlayer = 'X';
  gameOver = false;
  statusEl.textContent = `Player X's turn`;
  boxes.forEach(b => {
    b.textContent = '';
    b.classList.remove('disabled');
  });
  render();
}

init();
</script>
</body>
</html>
