<style>
*{margin:0;padding:0;box-sizing:border-box}
body{font-family:'Segoe UI',system-ui,sans-serif;background:#0f1117;color:#e1e4ea;min-height:100vh;padding:20px;display:flex;flex-direction:column;align-items:center;justify-content:center}
