<body>
<h1>🏀 Tic Tac Toe</h1>
<div class="buttons">
  <button id="restart">Play Again</button>
</div>
<div id="board"></div>
<div id="status"></div>
<div id="message"></div>
<script>
const HUMAN='X',COMP='O';
const SIZE=3;
const HUMAN_SCORE=1,COMP_SCORE=0;
let board=[],humanTurn=true,gameOver=false;

function init() {
  board=[Array(SIZE).fill(null),Array(SIZE).fill(null),Array(SIZE).fill(null)];
  humanTurn=true;
  gameOver=false;
  document.getElementById('status').textContent='Your turn (X)';
  document.getElementById('message').textContent='';
  document.getElementById('board').innerHTML='';
  for(let r=0;r<SIZE;r++){
    for(let c=0;c<SIZE;c++){
      const d=document.createElement('div');
      d.className='box' + (board[r][c]===HUMAN?' played':'');
      d.dataset.r=r;d.dataset.c=c;
      d.addEventListener('click',()=>handleClick(r,c));
      document.getElementById('board').appendChild(d);
    }
  }
}

function handleClick(r,c){
  if(gameOver||board[r][c]!=null)return;
  board[r][c]=humanTurn?HUMAN:COMP;
  humanTurn=false;
  document.getElementById('status').textContent=humanTurn?'Your turn (X)':`Computer (${COMP}) is thinking...`;
  render();
  setTimeout(computerMove,300);
}

function computerMove(){
  if(gameOver)return;
  let r=-1,c=-1;
  // First, look for a winning move for O
  for(let i=0;i<SIZE;i++)for(let j=0;j<SIZE;j++)if(board[i][j]===COMP){
    if(isWinningBoard(board,i,j))return[i,j];
  }
  // Then, block HUMAN's winning move
  for(let i=0;i<SIZE;i++)for(let j=0;j<SIZE;j++)if(board[i][j]===HUMAN){
    if(isWinningBoard(board,i,j))return[i,j];
  }
  // Finally, fill empty spots
  for(let i=0;i<SIZE;i++)for(let j=0;j<SIZE;j++)if(board[i][j]===null)return[i,j];
  // If none, pick center if available
  if(board[1][1]===null)return[1,1];
  // Otherwise random
  for(let i=0;i<SIZE;i++)for(let j=0;j<SIZE;j++)if(board[i][j]===null)return[i,j];
  // Random non-empty spot
  let r=0,c=0;
  while(board[r][c]===null){
    r=Math.floor(Math.random()*SIZE);
    c=Math.floor(Math.random()*SIZE);
  }
  return[r,c];
}

function isWinningBoard(board, r, c){
  const rows=board.map(r=>r[c]);
  if(rows.some(v=>v===COMP))return true;
  const cols=board.slice().map((row,i)=>row[i]);
  if(cols.some(v=>v===COMP))return true;
  const diags=[board[0],board[4],board[8]];
  if(diags.some(v=>v===COMP))return true;
  return false;
}

function isFull(board){
  for(let r=0;r<SIZE;r++)for(let c=0;c<SIZE;c++)if(board[r][c]===null)return false;
  return true;
}

function getWinner(board){
  const rows=board.map(r=>r.slice());
  const cols=board.map((row,i)=>row.slice());
  const diags=[board[0],board[4],board[8],board[2,4,6],board[6,4,0]];
  const all=[...rows,...cols,...diags];
  let winner=null;
  all.forEach(v=>{if(v!==null && v!==null && all.filter(x=>x!==null).length===1)winner=v;});
  return winner;
}

function checkGameOver(){
  const winner=getWinner(board);
  if(winner){
    if(winner===HUMAN){gameOver=true;document.getElementById('message').textContent='You win! Congratulations!';document.getElementById('message').style.background='rgba(110,231,183,.2)';}
    else if(winner===COMP){gameOver=true;document.getElementById('message').textContent='Computer wins! Better luck next time.';document.getElementById('message').style.background='rgba(248,81,73,.2)';}
  }
  if(isFull(board))gameOver=true;document.getElementById('message').textContent='It\'s a draw!';document.getElementById('message').style.background='rgba(232,81,135,.2)';
}

function render(){
  const b=board;
  for(let r=0;r<SIZE;r++)for(let c=0;c<SIZE;c++)document.getElementById('board').childElementCount?document.getElementById('board').childElementCount--:-1;
  const boxs=document.querySelectorAll('#board .box');
  boxs.forEach((el,i)=>el.style.background=b[r][c]||'');
  for(let r=0;r<SIZE;r++)for(let c=0;c<SIZE;c++)document.getElementById('board').childElementCount?document.getElementById('board').childElementCount--:-1;
  document.querySelectorAll('#board .box').forEach(el=>el.classList.remove('x','o','played'));
  document.querySelectorAll('#board .box[data-r="'+(r+1)+'"][data-c="'+(c+1)+'"]').forEach(el=>el.classList.add(humanTurn?'x':'o'));
}

function handleWin(){
  document.getElementById('status').textContent='Game Over!';
  const winner=getWinner(board);
  if(winner){
    if(winner===HUMAN){document.getElementById('message').textContent='You win!';document.getElementById('message').style.background='#6ee7b7';}
    else if(winner===COMP){document.getElementById('message').textContent='Computer wins!';document.getElementById('message').style.background='#f85149';}
  }
  else{document.getElementById('message').textContent='Draw!';document.getElementById('message').style.background='#1a213a';}
  document.getElementById('message').style.display='block';
}

function handleTie(){
  document.getElementById('status').textContent='Tie!';
  document.getElementById('message').textContent='It\'s a draw!';document.getElementById('message').style.background='rgba(232,81,135,.3)';
  document.getElementById('message').style.display='block';
}

function handleWinningMove(){
  document.getElementById('status').textContent='Computer wins!';
  document.getElementById('message').textContent='Computer wins! Better luck next time.';document.getElementById('message').style.background='rgba(248,81,73,.2)';
  document.getElementById('message').style.display='block';
}

function handleHumanWin(){
  document.getElementById('status').textContent='You win!';
  document.getElementById('message').textContent='You win! Congratulations!';document.getElementById('message').style.background='#6ee7b7';document.getElementById('message').style.display='block';
}

function handleComputerWin(){
  document.getElementById('status').textContent='Computer wins!';
  document.getElementById('message').textContent='Computer wins! Better luck next time.';document.getElementById('message').style.background='rgba(248,81,73,.2)';document.getElementById('message').style.display='block';
}

function handleDraw(){
  document.getElementById('status').textContent='Draw!';
  document.getElementById('message').textContent='It\'s a draw!';document.getElementById('message').style.background='rgba(232,81,135,.3)';document.getElementById('message').style.display='block';
}

function restart(){
  init();
}

function main(){
  init();
  document.getElementById('restart').addEventListener('click',restart);
  document.getElementById('restart').addEventListener('keydown',e=>{
    if(e.key==='Enter')restart();
  });
  document.addEventListener('keydown',e=>{
    if(e.key==='ArrowUp'||e.key==='w')e.preventDefault();
  });
  // Computer's AI moves on the next turn
  setTimeout(()=>{if(!gameOver){humanTurn=false;document.getElementById('status').textContent='Computer (${COMP}) is thinking...';document.getElementById('message').textContent='';document.getElementById('board').innerHTML='';render();},300});
}

document.addEventListener('DOMContentLoaded',main);
</script>
