<title>Tic Tac Toe</title>
<style>
*{margin:0;padding:0;box-sizing:border-box}
body{background:#1a1a2e;color:#eee;font-family:system-ui,sans-serif;display:flex;justify-content:center;align-items:center;min-height:100vh;padding:20px}
#game{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;padding:25px;background:#16213e;border-radius:16px}
#board{display:grid;grid-template-columns:repeat(3,1fr);gap:5px}
.cell{width:100px;height:100px;border-radius:12px;background:#2a2a4a;cursor:pointer;display:flex;align-items:center;justify-content:center;transition:transform .15s,box-shadow .15s}
.cell:hover{transform:scale(1.1);box-shadow:0 0 20px #0f3460}
.cell.filled{transform:scale(1)}
#messages{margin-top:15px;background:#16213e;border-radius:12px;padding:12px 16px;border:1px solid #0f3460}
#messages h3{font-size:1.1rem;margin-bottom:8px;color:#e94560}
#messages .turn{color:#888;font-size:0.9rem}
#messages .result{font-size:1.5rem;color:#00c853;font-weight:bold}
#messages .win{color:#e94560}
#messages .loss{color:#e94560}
#restart{margin-top:10px;padding:8px 16px;border:none;border-radius:10px;background:#0f3460;color:#fff;font-weight:bold;cursor:pointer}
#restart:hover{background:#1a538a}
</style>
</head>
<body>
<div id="game">
  <div id="board"></div>
  <div id="messages"></div>
  <button id="restart">Play Again</button>
</div>
<script>
const cells=document.querySelectorAll('.cell'),msg=document.getElementById('messages'),restart=document.getElementById('restart');
let board=[],playerX=0,playerO=0,gameActive=true;

function init(){
  board=[['','',''],['','',''],['','',''],['','','']];
  cells.forEach(c=>c.textContent='');playerX=0;playerO=0;gameActive=true;
  msg.innerHTML='';
  restart.disabled=false;
  updateTurnLabel();
}

function getTurnLabel(){
  if(gameActive&&playerX<9)return 'X (you)';
  if(gameActive&&playerO<9)return 'O (computer)';
  return '…';
}

function updateTurnLabel(){
  const t=getTurnLabel();msg.innerHTML=`<h3>${t} turn</h3><p class="turn">${t}</p>`;
}

function render(){
  cells.forEach((c,i)=>{
    c.textContent=board[i].join(' X ')||'';
    c.classList.toggle('filled',!!board[i].length);
    c.classList.toggle('playerX',board[i].includes(' X'));
    c.classList.toggle('playerO',board[i].includes(' O'));
  });
}

function checkWinner(){
  const lines=[
    [0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]
  ];
  for(const [a,b,c] of lines){
    if(board[a]&&board[a][0]===board[a][1]&&board[a][1]===board[a][2]){return board[a][0];}
    if(board[b]&&board[b][0]===board[b][1]&&board[b][1]===board[b][2]){return board[b][0];}
    if(board[c]&&board[c][0]===board[c][1]&&board[c][1]===board[c][2]){return board[c][0];}
  }
  return null;
}

function updateScore(){
  if(playerX>playerO)return 'X wins!';
  if(playerO>playerX)return 'O wins!';
  return 'Draw!';
}

function checkGameOver(){
  const winner=checkWinner();
  if(winner){
    gameActive=false;
    const res=checkGameOver();
    msg.innerHTML=`<div class="result">${res}</div><div class="win">You win! 🎉</div><div class="loss">Computer wins…</div>`;
    restart.disabled=true;
  } else if(board.every(r=>r==='')){gameActive=false;msg.innerHTML=`<div class="result">Draw! 🤝</div>`;}
}

cells.forEach(c=>c.addEventListener('click',()=>{
  if(!gameActive)return;
  const row=c.dataset.row,col=c.dataset.col;
  if(board[row][col]!=='')return;
  board[row][col]=' X ';
  c.textContent=' X ';c.classList.add('filled');c.classList.add('playerX');
  updateTurnLabel();render();checkWinner();updateScore();checkGameOver();
}));

restart.onclick=()=>{init();}
init();
</script>
</body>
</html>
