const $ = id => document.getElementById(id);
const STORAGE_KEY = 'todoList';

function load() {
  const v = localStorage.getItem(STORAGE_KEY);
  if (v) return JSON.parse(v);
  return [];
}

function save(data) {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
}

function getAll() {
  return load();
}

function getActive() {
  return getAll().filter(t => !t.completed);
}

function getCompleted() {
  return getAll().filter(t => t.completed);
}

function addTask(text) {
  if (!text.trim()) return;
  const data = getAll();
  data.push({ id: Date.now(), text: text.trim(), completed: false });
  save(data);
  render();
}

function toggle(id) {
  const data = getAll();
  const t = data.find(item => item.id === id);
  if (t) t.completed = !t.completed;
  save(data);
  render();
}

function deleteTask(id) {
  const data = getAll();
  data = data.filter(t => t.id !== id);
  save(data);
  render();
}

function filter(selected) {
  const data = getAll();
  if (selected === 'active') return data.filter(t => !t.completed);
  if (selected === 'completed') return data.filter(t => t.completed);
  return data;
}

function render() {
  const data = getAll();
  const ul = $('list');
  ul.innerHTML = '';
  const items = filter('all');
  if (items.length === 0) {
    ul.innerHTML = '<li><span class="completed">Aucune tâche</span></li>';
    return;
