    if (t.completed) li.classList.add('completed');
    const input = document.createElement('input');
    input.type = 'checkbox';
    input.checked = t.completed;
    li.appendChild(input);
    li.appendChild(document.createTextNode(t.text));
    li.appendChild(document.createElement('button'));
    li.appendChild(document.createTextNode('')) ;
    li.appendChild(document.createElement('span'));
    li.appendChild(document.createElement('button'));
    const btn = li.querySelector('button');
    btn.textContent = t.completed ? 'X' : '+';
    btn.title = t.completed ? 'Détruire' : 'Ajouter';
    btn.onclick = () => { toggle(t.id); };
    ul.appendChild(li);
  });
}

$('addBtn').onclick = () => addTask(localStorage.getItem('inputText') || '');
$('input').onkeydown = e => { if (e.key === 'Enter') addTask(localStorage.getItem('inputText') || ''); };

$('input').addEventListener('keydown', e => {
  if (e.key === 'Enter') {
    e.preventDefault();
    addTask(localStorage.getItem('inputText') || '');
  }
});

function init() {
  render();
}
init();
</script>
</body>
</html>
