<div id="filterPanel">
  <button data-filter="all" class="active">Toutes</button>
  <button data-filter="active" class="">En cours</button>
  <button data-filter="completed" class="">Terminées</button>
</div>
<script>
const $ = id => document.getElementById(id);
let tasks = [];

function load() {
  const raw = localStorage.getItem('todoTasks');
  if (raw) tasks = JSON.parse(raw);
}

function save() { localStorage.setItem('todoTasks', JSON.stringify(tasks)); }

function addTask(text) {
  if (!text.trim()) return;
  tasks.push({ id: Date.now(), text: text.trim(), done: false });
  save();
  render();
}

function toggleDone(id) {
  const t = tasks.find(x => x.id === id);
  if (t) t.done = !t.done;
  save();
  render();
}

function deleteTask(id) {
  tasks = tasks.filter(x => x.id !== id);
  save();
  render();
}

function filterTasks(filter) {
  tasks = tasks.filter(t => (filter === 'all' ? true : t.done === filter));
  const btns = $('filterPanel').children;
  btns.forEach(b => b.classList.toggle('active', b.dataset.filter === filter));
  render();
}

function render() {
  const list = $('taskList');
