      <span>${escapeHtml(t.text)}</span>
      <button onclick="toggleDone(${t.id})" ${t.done ? 'disabled' : ''}>✔</button>
      <button onclick="deleteTask(${t.id})" style="background:#d9534f">✕</button>
    </li>`).join('') : '<li style="padding:.8rem 1rem;background:#1a1d2e;border:1px solid #2a2d3a">Aucune tâche</li>';
}

function escapeHtml(s) { const d = { '&':'&amp;', "'":&apos;}; return String(s).replace(/[&<>"']/g, d); }

$('taskForm').onsubmit = e => { e.preventDefault(); const v = $('taskInput').value; addTask(v); $('taskInput').value = ''; };
document.querySelectorAll('.btns button').forEach(b => b.onclick = () => filterTasks(b.dataset.filter));
document.querySelectorAll('.btns button').forEach(b => b.classList.add('active'));
$('filterPanel').onkeydown = e => { if (e.key === 'Enter') { e.preventDefault(); const b = e.target.closest('.btns button'); filterTasks(b.dataset.filter); } };
load(); render();
</script>
</body>
</html>
