form{display:flex;gap:.8rem;margin-bottom:1.5rem;max-width:520px;width:100%}
input{flex:1;padding:.65rem 1rem;border:1px solid #30363d;border-radius:8px;background:#1e2030;color:#e1e4ea;font-size:1rem;outline:none}
input:focus{border-color:#a78bfa;box-shadow:0 0 0 2px rgba(167,139,250,.15)}
button{padding:.65rem 1.2rem;border:none;border-radius:8px;cursor:pointer;font-size:1rem;font-weight:600;transition:.2s}
button:active{transform:scale(.97)}
.add{background:#a78bfa;color:#1e2030}
.clear{background:#ef4444;color:#ffffff}
.delete{background:#6b7280;color:#ffffff}
.delete:hover{background:#8b8fa6}
.list{width:100%;max-width:600px;height:320px;overflow-y:auto}
.item{display:flex;align-items:center;gap:.8rem;margin:.5rem 0;padding:.5rem 1rem;border-radius:10px;transition:.2s}
.item.completed{text-decoration:line-through;color:#6b7280}
.item .checkbox{width:18px;height:18px;border:2px solid #30363d;border-radius:50%;transition:.2s}
.item.completed .checkbox{background:#a78bfa;color:#1e2030}
.item .checkbox.checked{border-color:#ef4444;color:#ef4444}
.item .title{flex:1;font-size:.95rem;word-break:break-word}
.item .title.done{color:#6b7280;text-decoration:arrow-down;opacity:.6}
.item .title.done.active{color:#ef4444;text-decoration:arrow-down active}
.item .title.done.active .checkbox{border-color:#ef4444;color:#ef4444}
.item .title.done.active .checkbox.checked{border-color:#ef4444;color:#ef4444}
.item .remove{background:transparent;border:none;cursor:pointer;padding:.2rem .5rem;margin-left:.5rem;font-size:.9rem;color:inherit;transition:.2s}
.item .remove:hover{color:#ef4444}
</style>
</head>
<body>
<h1>📊 To-Do List</h1>
<form id="taskForm">
  <input type="text" id="newTask" placeholder="Ajouter une tâche…" autocomplete="off" required>
  <button type="submit">+ Ajouter</button>
</form>
<div class="list" id="taskList"></div>
<script>
const STORAGE_KEY = 'todoList';
const $ = id => document.getElementById(id);
const form = $('taskForm');
const input = $('newTask');
const list = $('taskList');

function load() {
  try { const v = localStorage.getItem(STORAGE_KEY); if (v) list.innerHTML = v; }
  catch(e) { /* ignore */ }
}

function save() { localStorage.setItem(STORAGE_KEY, list.innerHTML); }

function generateId() { return Math.random().toString(36).slice(2, 9); }

function addTask() {
  const text = input.value.trim();
  if (!text) return;
  const id = generateId();
  const completed = false;
  const item = { id, text, completed, checkbox: true, remove: true };
  list.innerHTML += render(item);
  save();
  input.value = '';
  input.focus();
}

function render(item) {
  const cls = item.completed ? 'completed' : '';
  const doneClass = item.completed ? 'done' : '';
  const checked = item.completed;
  return `
    <div class="item ${cls} ${doneClass}" tabindex="-1">
      <input type="checkbox" ${checked ? 'checked' : ''} class="checkbox" id="c-${item.id}" />
      <span class="title ${item.completed ? 'done' : ''}" tabindex="0" onkeydown={(e) => e.key === 'Enter' && item.completed ? remove(item) : e.preventDefault()}>${item.text}</span>
      <button class="remove" onclick="remove(${item.id})">✕</button>
    </div>`;
}

function remove(id) {
  if (!confirm('Supprimer cette tâche ?')) return;
  list.innerHTML = list.innerHTML.replace(`<div class="item ${id}...">`, '');
  save();
}

function toggle(id) {
  const el = document.getElementById(`c-${id}`);
  if (el) el.checked = !el.checked;
  save();
}

function toggleAll() {
  const items = list.querySelectorAll('.item');
  items.forEach(i => i.classList.toggle('completed', i.classList.contains('completed')));
  save();
}

function clearAll() {
  if (confirm('Supprimer toutes les tâches ?')) list.innerHTML = '';
  save();
}

form.addEventListener('submit', (e) => { e.preventDefault(); addTask(); });

['add', 'toggle', 'toggleAll', 'clear'].forEach(m => {
  form.addEventListener('click', () => form.querySelector(`[data-${m}]`).click());
});

load();
</script>
</body>
</html>
