<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Calculator</title>
<style>
*{margin:0;padding:0;box-sizing:border-box}
body{font-family:'Segoe UI',system-ui,sans-serif;background:#0f1117;color:#e0e0e0;min-height:100vh;display:flex;flex-direction:column;align-items:center;justify-content:center}
#app{width:320px;padding:20px;background:#161b23;border-radius:12px;box-shadow:0 4px 16px rgba(0,0,0,.4)}
#display{width:100%;font-size:2.4rem;font-weight:700;padding:16px 10px;background:#0f1117;border:1px solid #2a2d35;border-radius:8px;color:#66c2ff;text-align:right;letter-spacing:.04em;user-select:none}
button{width:48px;height:48px;border-radius:8px;margin:4px;cursor:pointer;font-size:1.1rem;font-weight:600;transition:transform .1s,background .15s}
button:active{transform:scale(.93)}
button.primary{background:#2a2d35;color:#fff}
button.primary:hover{background:#3a3e47}
button.primary.active{background:#444}
button.primary.danger{background:#6a0000;color:#fff}
button.secondary{background:#1a1d27;color:#aaa}
button.secondary:hover{background:#242835}
button.asterisk{background:#2a2d35;color:#fff;border:2px solid #444}
button.asterisk:hover{background:#3a3e47}
button.asterisk.active{background:#555}
button.digit{background:#0f1117;border:2px solid #2a2d35;color:#aaa;font-size:1.2rem}
button.digit:hover{background:#161b23}
button.digit.active{background:#444}
button.divide{background:#2a2d35;color:#fff;border:2px solid #444}
button.divide:hover{background:#3a3e47}
button.divide.active{background:#555}
button.plus{background:#2a2d35;color:#fff;border:2px solid #444}
button.plus:hover{background:#3a3e47}
button.plus.active{background:#555}
button.minus{background:#2a2d35;color:#fff;border:2px solid #444}
button.minus:hover{background:#3a3e47}
button.minus.active{background:#555}
button.equals{background:#2a2d35;color:#fff;border:none}
button.equals:hover{background:#3a3e47}
button.equals.active{background:#555}
button.clear{background:#2a2d35;color:#fff;border:2px solid #444;font-size:1.2rem}
button.clear:hover{background:#3a3e47}
button.clear.active{background:#555}
</style>
</head>
<body>
<div id="app">
  <input type="text" id="display" readonly>
  <div style="margin-top:10px;display:flex;gap:10px;align-items:center">
    <button class="digit" data-key="1">1</button>
    <button class="digit" data-key="2">2</button>
    <button class="digit" data-key="3">3</button>
    <button class="digit" data-key="4">4</button>
    <button class="digit" data-key="5">5</button>
    <button class="digit" data-key="6">6</button>
    <button class="digit" data-key="7">7</button>
    <button class="digit" data-key="8">8</button>
    <button class="digit" data-key="9">9</button>
    <button class="digit" data-key="0">0</button>
    <button class="asterisk" data-key="*">*</button>
    <button class="divide" data-key="/">÷</button>
    <button class="plus" data-key="+">+</button>
    <button class="minus" data-key="-">−</button>
    <button class="equals" data-key="=">=</button>
    <button class="clear" data-key="C">C</button>
    <button class="clear" data-key="CE">CE</button>
  </div>
</div>
<script>
const keys = document.querySelectorAll('button[data-key]');
let display, firstOperand, operator, waitingForSecond = false;
const display = document.getElementById('display');

function updateDisplay() {
  display.value = waitingForSecond ? firstOperand + operator : firstOperand;
}

function handleInput(key) {
  if (waitingForSecond) {
    firstOperand = key;
    operator = '';
    waitingForSecond = false;
  } else if (key === 'C' || key === 'CE') {
    firstOperand = '0';
    operator = '';
    waitingForSecond = false;
    updateDisplay();
  } else if (['+', '-', '*', '/'].includes(key)) {
    if (waitingForSecond) {
      firstOperand = key;
      operator = key;
      waitingForSecond = false;
    } else {
      operator = key;
      waitingForSecond = true;
    }
  } else if (['.', '0-9'].includes(key)) {
    if (waitingForSecond) {
      firstOperand = key;
      waitingForSecond = false;
    } else {
      if (!display.value.includes('.') && key !== '0') {
        firstOperand = firstOperand.toString() + key;
      } else {
        firstOperand = firstOperand.toString() + key;
      }
    }
    updateDisplay();
  }
}

keys.forEach(k => k.addEventListener('click', () => handleInput(k.target)));
display.addEventListener('keydown', e => {
  const m = e.key;
  const isDigit = /[0-9.]/.test(m);
  const isOperator = ['+', '-', '*', '/'].includes(m);
  const isEqual = m === '=';
  if (['Backspace', 'ArrowBack', 'ArrowLeft'].includes(m)) {
    e.preventDefault();
  } else if (isDigit) {
    e.preventDefault();
    handleInput(m);
  } else if (isOperator) {
    e.preventDefault();
    handleInput(m);
  } else if (isEqual) {
    e.preventDefault();
    handleInput('=');
  }
});
</script>
</body>
