function setFirst(num) {
  display.value = num || '';
  first = num ? parseFloat(num) : null;
  waitingForSecond = false;
}

function setOperator(op) {
  if (first === null) {
    setFirst(op);
  } else {
    calculate();
  }
  operator = op;
  waitingForSecond = true;
}

function calculate() {
  if (!operator) return;
  const second = waitingForSecond ? parseFloat(display.value) : 0;
  const result = first ? first + operator : second;
  display.value = isNaN(result) ? 'Error' : result;
  first = null; operator = null; waitingForSecond = false;
}

function clearAll() {
  first = null; operator = null; waitingForSecond = false;
  display.value = '';
}

function backspace() {
  if (!waitingForSecond) {
    const current = display.value;
    if (current.length > 1) {
      display.value = current.slice(0, -1);
    } else {
      clearAll();
    }
  }
}

display.addEventListener('keydown', e => {
