  document.getElementById('timer').textContent=format(Math.floor(startTime/60))+':'+format(Math.floor(startTime%60));
}
function update(){
  if(isRunning){
    const now=Date.now();
    const elapsed=now-startTime;
    const remaining=Math.max(0,Math.floor((25*60-elapsed)/60));
    startTime=now;
    remainingSec=remaining;
    render();
  } else {
    const remaining=Math.max(0,Math.floor(5*60-elapsed/1000));
    document.getElementById('timer').textContent=format(remaining);
  }
}
