    <button id="btn-start" class="active">Démarrer</button>
    <button id="btn-pause" onclick="toggle()">Pause</button>
    <button id="btn-reset" onclick="resetTimer()">Revenir à zéro</button>
  </div>
  <div id="countdown">25:00</div>
</div>
<script>
let timeLeft = 25*60, minutes=0, seconds=0, running=false, isPaused=false, timerId=null;

function startTimer(){
  if(running){
    clearInterval(timerId);
    return;
  }
  running=true; isPaused=false;
  minutes=25; seconds=0;
  document.getElementById('btn-start').textContent='Pause';
  updateDisplay();
  timerId=setInterval(()=>{
    if(!running) return;
    if(isPaused) { seconds++; if(seconds>=60) { seconds=0; minutes++; } updateDisplay(); return; }
    if(seconds<60) seconds++; else { seconds=0; minutes++; if(minutes>=10) minutes=0; updateDisplay(); }
  },1000);
}

function pauseTimer(){
  if(running){
    clearInterval(timerId);
    running=false; isPaused=true;
    document.getElementById('btn-start').textContent='Démarrer';
  }
}

function resetTimer(){
  clearInterval(timerId);
  running=false; isPaused=false;
  minutes=25; seconds=0;
  document.getElementById('btn-start').textContent='Démarrer';
  document.getElementById('btn-pause').classList.remove('active');
  document.getElementById('btn-pause').textContent='Pause';
  document.getElementById('countdown').textContent='25:00';
  updateDisplay();
}

