    <button id="reset">🔄 Réinitialiser</button>
  </div>
  <div id="endMsg"></div>
</div>
<script>
const $ = id => document.getElementById(id);
let timerId = null;
let isRunning = false;
let seconds = 0;
let isPaused = false;

function start() {
  if (isRunning) return;
  isRunning = true;
  seconds = 25 * 60;
  document.getElementById('start').disabled = true;
  document.getElementById('pause').disabled = false;
  document.getElementById('reset').disabled = false;
  document.getElementById('endMsg').style.display = 'none';
  updateDisplay();
  timerId = setInterval(() => {
    seconds--;
    updateDisplay();
    if (seconds <= 0) {
      clearInterval(timerId);
      isRunning = false;
      document.getElementById('start').disabled = false;
      document.getElementById('start').focus();
      showEndMessage();
    }
  }, 1000);
}

function pause() {
  if (isRunning && !isPaused) {
    isPaused = true;
    clearInterval(timerId);
    timerId = null;
  }
}

function reset() {
  if (isRunning) {
    isRunning = false;
    clearInterval(timerId);
    isPaused = false;
    seconds = 25 * 60;
    document.getElementById('start').disabled = false;
    document.getElementById('start').focus();
    updateDisplay();
  }
}

function updateDisplay() {
  const m = String(seconds / 60).padStart(2, '0');
  const s = String(seconds % 60).padStart(2, '0');
  document.getElementById('timer').innerHTML = `${m}:${s}`;
  const pct = Math.min((seconds / 1500) * 100, 100);
  document.getElementById('progress').classList.add('filled');
  document.getElementById('progress').classList.remove('idle', 'busy');
  document.getElementById('progress').classList.add(`busy${pct > 0 ? '' : ' idle'}`);
  document.getElementById('progress').style.background = `linear-gradient(90deg,#58a6ff,#38bdf8)`;
  document.getElementById('progress').style.transform = `scale(${pct / 100})`;
}

function showEndMessage() {
  document.getElementById('endMsg').textContent =
    `✅ Session terminée ! ${seconds / 60} min de pause`;
  document.getElementById('endMsg').classList.add('show');
}

document.getElementById('start').addEventListener('click', start);
document.getElementById('pause').addEventListener('click', pause);
document.getElementById('reset').addEventListener('click', reset);
</script>
</body>
