<body>
<canvas id="gameCanvas" width="800" height="100"></canvas>
<div id="overlay">
  <div id="score">Score: 0</div>
  <div id="lives">Lives: 3</div>
  <div id="message"></div>
  <button id="restartBtn">Play Again</button>
</div>
<script>
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');
const overlay = document.getElementById('overlay');
const scoreEl = document.getElementById('score');
const livesEl = document.getElementById('lives');
const msgEl = document.getElementById('message');
const btn = document.getElementById('restartBtn');

const COLS = 10, ROWS = 4, BRICK_W = 60, BRICK_H = 20, GAP = 3;
const BRICKS = [];
const PADDLE_W = 90, PADDLE_H = 10, PADDLE_SPEED = 6;
const BALL_SIZE = 14, BALL_SPEED = 5;
const BALL_COLOR = '#fff';
const PADDLE_COLOR = '#444';
const BRICK_COLOR = ['#222', '#4caf50', '#ff6b35'];
const PADDLE_COLOR = '#0f3460';
const GROUND = canvas.height - 10;

function initBricks() {
  BRICKS = [];
  for(let r = 0; r < ROWS; r++) {
    for(let c = 0; c < COLS; c++) {
      const color = BRICK_COLOR[r % 3];
      BRICKS.push({x: c * (BRICK_W + GAP) + (BRICK_W - BRICK_W) / 2, y: r * (BRICK_H + GAP) + 8, hit: false});
    }
  }
}

function drawBricks() {
  ctx.fillStyle = '#111';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  for(const b of BRICKS) {
    ctx.fillStyle = b.hit ? BRICK_COLOR[1] : BRICK_COLOR[0];
    ctx.fillRect(b.x, b.y, BRICK_W, BRICK_H);
    if(b.hit) ctx.fillStyle = BRICK_COLOR[2];
    ctx.fillRect(b.x, b.y, BRICK_W, BRICK_H);
    ctx.fillStyle = '#000';
    ctx.font = '12px system-ui';
    ctx.textAlign = 'left';
    ctx.fillText(b.x, b.x, b.y + BRICK_H + 2);
    ctx.fillText(b.x + BRICK_W, b.x, b.y + 4);
  }
}

function drawPaddle() {
  ctx.fillStyle = PADDLE_COLOR;
  ctx.fillRect(canvas.width - PADDLE_W, GROUND - 10, PADDLE_W, 10);
}

function drawBall() {
  ctx.beginPath();
  ctx.arc(canvas.width / 2, canvas.height / 2, BALL_SIZE, 0, Math.PI * 2);
  ctx.fillStyle = BALL_COLOR;
  ctx.fill();
  ctx.strokeStyle = '#000';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(canvas.width / 2, canvas.height / 2, BALL_SIZE * 0.75, 0, Math.PI * 2);
  ctx.stroke();
}

function draw() {
  ctx.fillStyle = '#000';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  drawBricks();
  drawPaddle();
  drawBall();
}

function update() {
  if(!gameActive) return;

  // Paddle controls
  let dx = 0;
  if(event.key === 'ArrowRight') dx = PADDLE_SPEED;
  else if(event.key === 'ArrowLeft') dx = -PADDLE_SPEED;
  else if(event.key === ' ' || event.key === 'ArrowRight' || event.key === 'ArrowLeft') dx = 0;

  // Paddle movement
  if(dx !== 0) {
    const target = dx;
    const paddleLeft = canvas.width - PADDLE_W;
    if(paddleLeft - PADDLE_W > target - 10) target = canvas.width - PADDLE_W;
    if(paddleLeft - PADDLE_W < target + 10) target = 10;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawPaddle();
    drawBall();
    draw();
    requestAnimationFrame(loop);
    return;
  }

  ctx.clearRect(0, 0, canvas.width, canvas.height);
  drawPaddle();
  drawBall();
  draw();
  requestAnimationFrame(loop);
}

function loop() {
  ctx.fillStyle = '#000';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  drawBricks();
  drawPaddle();
  drawBall();
  update();
  requestAnimationFrame(loop);
}

function resetGame() {
  gameActive = true;
  overlay.style.display = 'none';
  initBricks();
  scoreEl.textContent = 'Score: 0';
  livesEl.textContent = 'Lives: 3';
  msgEl.textContent = '';
  draw();
}

canvas.addEventListener('click', (e) => {
  if(!gameActive) return;
  const rect = canvas.getBoundingClientRect();
  const x = e.clientX - rect.left;
  const col = Math.floor(x / (BRICK_W + GAP));
  const row = Math.floor((e.clientY - rect.top) / (BRICK_H + GAP));
  if(row >= 0 && row < ROWS && col >= 0 && col < COLS && !BRICKS[row * COLS + col].hit) {
    BRICKS[row * COLS + col].hit = true;
    scoreEl.textContent = 'Score: ' + (parseInt(scoreEl.textContent.split(':').pop()) + 1);
    draw();
    requestAnimationFrame(loop);
  }
});

