<body>
<h1>2048</h1>
<div id="board"></div>
<div id="overlay"><h2>Game Over</h2><p id="msg"></p><button id="newBtn">Play Again</button></div>
<div id="score">Score: 0</div>
<script>
const TILES=4,SIZE=8,COLS=4,EMPTY=0;
let grid, score, gameover, moveCount;

function init() {
  grid=[...Array(COLS).keys()];
  score=0;gameover=false;moveCount=0;
  document.getElementById('score').textContent='Score: 0';
  render();
}

function render() {
  const board=document.getElementById('board');
  board.innerHTML='';
  for(let c=0;c<COLS;c++){
    for(let r=0;r<TILES;r++){
      const tile=document.createElement('div');
      tile.className='tile';
      tile.dataset.r=c;tile.dataset.c=r;
      if(grid[c*TILES+r]===EMPTY) tile.classList.add('empty');
      else if(grid[c*TILES+r]===TILES*2) tile.classList.add('new');
      else if(grid[c*TILES+r]===TILES*4) tile.classList.add('merged');
      tile.onclick=()=>handleMove(tile);
      board.appendChild(tile);
    }
  }
  document.getElementById('msg').textContent='';
}

function handleMove(tile) {
  if(gameover) return;
  if(tile.classList.contains('new')) {
    grid[tile.dataset.r*TILES+tile.dataset.c]=2;
  } else {
    const r=tile.dataset.r;const c=tile.dataset.c;
    const val=grid[r*TILES+c];
    if(val===EMPTY) return;
    const dr=[-1,1,0,0],dc=[0,0,-1,1];
    for(let k=0;k<4;k++){
      const nr=r+dr[k],nc=c+dc[k];
      if(nr>=0&&nr<TILES&&nc>=0&&nc<TILES){
        if(grid[nr*TILES+nc]!==EMPTY){
          const merge=val+grid[nr*TILES+nc];
          if(merge>=TILES*2){
            grid[nr*TILES+nc]=merge;
            grid[r*TILES+c]=EMPTY;
            moveCount++;
            render();
            break;
          }
        }
      }
    }
  }
  render();
  if(!gameover) setTimeout(()=>init(),600);
}

function update() {
  let merged=0;
  for(let r=0;r<TILES;r++){
    let val=grid[r];
    let max=0, idx=-1;
    for(let c=0;c<TILES;c++){
      if(val>=TILES*2) {max=c;idx=c;}
    }
    if(idx!==-1){
      grid[r]=max;
      if(max>merged) merged=max;
    }
  }
  if(merged===0) merged=1;
  if(merged>0){
    grid[merged]=grid[merged-1];
    if(grid[merged-1]===grid[merged-2]) grid[merged-1]+=grid[merged-2];
    grid[merged-2]=EMPTY;
  }
  const mergedTiles=[...Array(TILES-1).keys()];
  if(mergedTiles.length){
    const idx=mergedTiles[Math.floor(Math.random()*mergedTiles.length)];
    grid[idx]=TILES*2;
    score+=mergedTiles.length*merged;
  }
}

document.addEventListener('keydown',e=>{
  if(gameover) return;
  if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)){
    e.preventDefault();
    if(e.key==='ArrowUp'||e.key==='ArrowDown'){
      moveCount++;
    }
    update();
    render();
  }
});

document.getElementById('newBtn').onclick=()=>{init()};
init();
</script>
</body>
</html>
