<body>
<div id="app">
  <div id="score">Score: 0</div>
  <div id="board"></div>
  <button id="restart">Restart Game</button>
  <button id="init">Start New Game</button>
  <div id="gameOver"></div>
</div>
<script>
const M=4,N=8,SIZE=256,CELL=24;
const grid=document.getElementById('board');
const scoreEl=document.getElementById('score');
const gameOverEl=document.getElementById('gameOver');
const restartBtn=document.getElementById('restart');
const initBtn=document.getElementById('init');

let gameOver=true, score=0, board=[], newTile=0;

function init(){
  score=0;gameOver=true;board=[];newTile=0;
  scoreEl.textContent='Score: 0';
  gameOverEl.textContent='';
  grid.innerHTML='';
  for(let r=0;r<M;r++)for(let c=0;c<N;c++){
    const cell=document.createElement('div');
    cell.className='cell';cell.dataset.r=r;cell.dataset.c=c;
    grid.appendChild(cell);
  }
}

function render(){
  const cells=grid.querySelectorAll('.cell');
  cells.forEach(cell=>{
    const r=+cell.dataset.r,s=+cell.dataset.c;
    cell.classList.toggle('active',r===0 && s===0);
    cell.classList.toggle('merged',board[r][s]!==null);
    cell.classList.toggle('new',board[r][s]===newTile);
    cell.classList.toggle('hidden',board[r][s]===null);
  });
}

function randomTile(){
  let val=0;
  do{val=Math.random()<.95?2:4}while(board[Math.floor(Math.random()*M)][Math.floor(Math.random()*N)]);
  board[Math.floor(Math.random()*M)][Math.floor(Math.random()*N)]=val;
}

function move(dir){
  const dr=0,dc=0;
  switch(dir){
    case 'ArrowUp':dc=-1;break;
    case 'ArrowDown':dc=1;break;
    case 'ArrowLeft':dr=-1;break;
    case 'ArrowRight':dr=1;break;
  }
  if(!dr&&!dc) return false;
  for(let r=0;r<M;r++){
    let head=0;
    for(let c=0;c<N;c++)if(board[r][c])head++;
    if(head===1){head=1;continue;}
    if(head>1){
      const val=board[r][head-1];
      if(val!==null){
        board[r][head-1]=null;
        for(let c=head;c<N;c++){
          if(board[r][c])board[r][c].val=val;
        }
      }
    }
  }
  if(!dr){for(let c=0;c<N;c++){let head=0;for(let r=M-1;r>=0;r--)if(board[r][c])head++;if(head>1){board[c][head-1]=null;for(let r=head-1;r>=0;r--)if(board[r][c])board[c][r]=board[c][r+1];}}
    return true;
  }
  for(let r=0;r<M;r++){let head=0;for(let c=N-1;c>=0;c--)if(board[c][r])head++;if(head>1){board[c][head-1]=null;for(let c=head-1;c>=0;c--)if(board[c][r])board[c][c+1]=board[c+1][r];}}
  return true;
}

function merge(row){
  for(let c=1;c<row.length;c++){
    if(row[c]!==null && row[c]===row[c-1])row[c]=row[c-1]*2;else row[c]=null;
  }
  let count=0;
  for(let c=0;c<row.length;c++)if(row[c]!==null)count++;
  return count;
}

function applyMove(dir){
  for(let r=0;r<M;r++){
    let row=board[r];
    if(dir==='ArrowUp'){
      row=merge(row);
    } else if(dir==='ArrowDown'){
      row.reverse();row=merge(row);row.reverse();
    } else if(dir==='ArrowLeft'){
      row=merge(row);
    } else if(dir==='ArrowRight'){
      row.reverse();row=merge(row);row.reverse();
    }
    board[r]=row;
  }
  if(move(dir))newTile=Math.random()<.95?2:4;
  else newTile=Math.random()<.2?4:2;
  render();
  scoreEl.textContent='Score: '+(score+=Math.abs(newTile*2));
}

function checkWin(){
  for(let r=0;r<M;r++)
    if(board[r].every(v=>v===2048))return true;
  return false;
}

function checkLose(){
  for(let r=0;r<M;r++)
    for(let c=0;c<N;c++)
      if(board[r][c]===null)return true;
  return false;
}

function checkGameOver(){
  if(!gameOver)return false;
  if(checkWin())return false;
  if(checkLose())gameOver=true;
  return gameOver;
}

function restart(){
  init();
  render();
}

init();
render();
initBtn.onclick=()=>{init();render()};
restartBtn.onclick=()=>{restart()};
</script>
