  boardDiv.innerHTML = '';
  board.forEach((v, i) => {
    const d = document.createElement('div');
    d.className = 'tile' + (v > 0 ? ' active' : v === 0 ? ' moved' : v === 2 ? ' tile-moved' : '');
    d.textContent = v;
    d.dataset.idx = i;
    boardDiv.appendChild(d);
  });
  board.forEach((v, i) => { if (v > 0) gameStarted = true; });
}

function getNeighbors(row, col) {
  const dirs = [
    [row-1, col], [row+1, col], [row, col-1], [row, col+1],
    [row-1, col-1], [row-1, col+1], [row+1, col-1], [row+1, col]
  ];
  return dirs.filter(r => r[0] >= 0 && r[0] < BOARD_SIZE && r[1] >= 0 && r[1] < BOARD_SIZE);
}

function merge(row, col) {
  let count = 0;
  row[col] += count;
  if (row[col] >= 4) row[col] -= 4; else count++;
  row[col+1] += count;
  if (row[col+1] >= 4) row[col+1] -= 4; else count++;
  return [row, count];
}

function move(row, col, direction) {
  let board = [...board];
  let neighbors = getNeighbors(row, col);
  if (!neighbors.length) return board;

  const [target, count] = merge(row, col);
  board[row][col] = 0;
  board[target[0]][target[1]] += count;
  board[row][col] = 0;
  return board;
}

function gameLoop() {
  const b = board;
  let updated = false;
  for (let r = 0; r < BOARD_SIZE; r++) {
    for (let c = 0; c < BOARD_SIZE; c++) {
      if (b[r][c] === 0) continue;
      const dirs = getNeighbors(r, c);
      if (dirs.length) {
        const [nr, nc] = dirs[0];
        b[r][c] = 0;
        b[nr][nc] += b[r][c];
        b[r][c] = 0;
        updated = true;
      }
    }
  }
  if (updated) render(b);
  else {
    score += Math.pow(2, board.flat().filter(v => v > 0).length);
    scoreEl.textContent = score;
    gameOverEl.textContent = 'Game Over! Your score: ' + score;
    gameOverEl.style.color = 'red';
    gameOverEl.style.fontWeight = 'bold';
    if (score <= 0) gameStarted = false;
  }
}

function handleKeyDown(e) {
  if (!gameStarted || gameStarted === false) return;
  if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(e.key)) {
    e.preventDefault();
    move(board, e.key === 'ArrowUp' ? 0 : e.key === 'ArrowDown' ? 1 : e.key === 'ArrowLeft' ? 2 : 3, e.key);
  } else if (e.key === ' ' || e.key === 'Enter') {
    e.preventDefault();
    init();
  }
}

function init() {
  board = Array.from({length: BOARD_SIZE}, () => Array.from({length: BOARD_SIZE}, () => 0));
  score = 0;
  scoreEl = document.getElementById('score');
  gameOverEl = document.getElementById('msg');
  boardDiv = document.getElementById('board');
  scoreEl.textContent = 0;
  gameOverEl.textContent = '';
  board.forEach(row => row.fill(0));
  gameLoop();
  board.forEach(row => row.fill(0));
  gameStarted = false;
  scoreEl.classList.remove('game-over');
  gameOverEl.textContent = '';
  board.forEach(row => row.fill(0));
}

function updateScoreEl() {
