<!DOCTYPE html>
<html lang="fr">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Minesweeper</title>
<style>
  *{margin:0;padding:0;box-sizing:border-box}
  body{background:#111;color:#eee;font-family:'Segoe UI',sans-serif;display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:100vh;user-select:none}
  h1{font-size:1.4rem;margin-bottom:8px;color:#e94560;letter-spacing:1px}
  .grid{display:grid;grid-template-columns:repeat(9,1fr);gap:2px;background:#222;border-radius:8px;padding:2px;width:300px;box-shadow:0 0 20px rgba(0,0,0,.5)}
  .cell{width:100%;height:100%;border-radius:4px;cursor:pointer;transition:background .2s}
  .cell:hover{background:#333}
  .cell.mined{background:#e94560;color:#fff}
  .cell.flagged{background:#4a4a4a;color:#e94560;font-weight:700}
  .cell.uncovered{background:#1a1a1a;color:#ccc}
  .cell.num{font-size:.9rem;font-weight:600}
</style>
</head>
<body>
<h1>🔥 Minesweeper</h1>
<div class="grid" id="grid"></div>
<script>
const COLS=9, ROWS=9, MINES=10;
let board, clicks, flagged, revealed;

function createGrid(){
  board=[[]];
  clicks=0; flagged=0; revealed=0;
  const minePositions=[];

  // Place mines randomly
  for(let i=0;i<MINES;i++){
    while(true){
      const r=Math.floor(Math.random()*ROWS);
      const c=Math.floor(Math.random()*COLS);
      if(!board[r][c]){minePositions.push([r,c]);break;}
    }
  }

  // Generate numbers
  for(let r=0;r<ROWS;r++){
    board[r]=[];
    for(let c=0;c<COLS;c++){
      if(minePositions.includes([r,c])){
        board[r][c]='mined';
      } else {
        let count=0;
        for(let dr=-1;dr<=1;dr++){
          for(let dc=-1;dc<=1;dc++){
            if(dr||dc) if(Math.abs(dr)+Math.abs(dc)!==1 && board[r+dr][c+dc]!=='mined') count++;
          }
        }
        board[r][c]=(count>0?'num:'+count:'uncovered');
      }
    }
  }
}

function render(){
  const g=document.getElementById('grid');
  g.innerHTML='';
  for(let r=0;r<ROWS;r++){
    for(let c=0;c<COLS;c++){
      const cell=document.createElement('div');
      cell.className='cell';
      cell.dataset.x=c;cell.dataset.y=r;
      if(revealed[r][c]) cell.className='uncovered';
      else if(flagged[r][c]) cell.className='flagged';
      else if(board[r][c]!=='mined') cell.className='num';
      else cell.className='mined';
      cell.onclick=()=>{
        if(revealed[r][c]) return;
        cell.classList.add('uncovered');
        revealed[r][c]=true;
        clicks++;
        if(board[r][c]!=='mined'){revealed[r][c]=true;clicks++;}
        checkWin();
      };
      cell.onclick=()=>{
        if(revealed[r][c]) return;
        cell.classList.remove('uncovered');
        revealed[r][c]=false;
        cell.classList.add('uncovered');
        revealed[r][c]=false;
        clicks--;
        if(board[r][c]!=='mined'){revealed[r][c]=false;clicks--;}
        checkWin();
      };
      g.appendChild(cell);
    }
  }
}

function updateFlag(){
  for(let r=0;r<ROWS;r++){
    for(let c=0;c<COLS;c++){
      const cell=document.getElementById(`c${c}r${r}`);
      if(cell) cell.textContent=(board[r][c]!=='mined')?'-':board[r][c];
    }
  }
}

function checkWin(){
  const uncovered=0;
  for(let r=0;r<ROWS;r++){
    for(let c=0;c<COLS;c++){
      if(revealed[r][c]) uncovered++;
    }
  }
  if(uncovered===ROWS*COLS-MINES){
    revealed.forEach(r=>r.forEach(c=>c.value=true));
    document.querySelectorAll('.cell.uncovered').forEach(c=>c.style.border='2px solid #e94560');
    alert('🏆 Victoire !');
  } else if(clicks>0){
    document.querySelectorAll('.cell.uncovered').forEach(c=>c.style.border='2px solid #444');
    document.querySelectorAll('.cell.flagged').forEach(c=>c.style.border='2px dashed #888');
    alert('Game over... ouais.');
  }
}

function toggleFlag(r,c){
  if(board[r][c]!=='mined'){
    board[r][c]='flagged';
    const cell=document.getElementById(`c${c}r${r}`);
    if(cell) cell.textContent='flag';
  } else {
    board[r][c]=flagged[r][c]!=='mined'?'num:'+flagged[r][c]+':-';
    const cell=document.getElementById(`c${c}r${r}`);
    if(cell) cell.textContent=flagged[r][c]!=='mined'?'-':board[r][c];
  }
  updateFlag();
  checkWin();
}

function init(){
  createGrid();
  render();
}

document.addEventListener('keydown',e=>{
  if(e.key==='ArrowUp'||e.key==='w'||e.key==='A') e.preventDefault();
  if(e.key==='ArrowDown'||e.key==='s'||e.key==='D') e.preventDefault();
  if(e.key==='ArrowLeft'||e.key==='a') e.preventDefault();
  if(e.key==='ArrowRight'||e.key==='d') e.preventDefault();
  if(e.key===' '){e.preventDefault();toggleFlag(r,c)}
});

init();
</script>
</body>
</html>
