#grid{display:grid;grid-template-columns:repeat(9,1fr);gap:2px;margin-bottom:12px}
.cell{width:42px;height:42px;border-radius:4px;cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:1.2rem;font-weight:700;position:relative}
.cell:hover{background:#1a1a1a}
.cell.revealed{background:#2a2a2a}
.cell.flagged{background:#3a3a3a}
.cell.flagged .mine{color:#f06599} /* couleurs spécifiques au drapeau */
#status{font-weight:bold}
</style>
