<body>
<h1>Démineur</h1>
<div id="status"></div>
<div id="grid"></div>
<script>
const COLS=9;const MINES=10;const TOTAL=COLS*COLS;
let mines=[];

// Génère un tableau aléatoire de 0/10 avec exactement 10 mines
function initMines(){
  mines=[];
  let filled=0;
  while(filled<MINES){
    const r=Math.floor(Math.random()*TOTAL);
    if(!mines.includes(r)){
      mines.push(r);
      filled++;
    }
  }
  mines.sort(() => Math.random()-0.5);
}

// Transforme un tableau 0/10 en symbole de mine/numérique
function getCell(val){
  if(val===0) return 0;
  if(val>=10) return 10;
  return val;
}

// Mise à jour du statut
function updateStatus(flag){
  const status=document.getElementById('status');
  if(flag){
    status.textContent='Victoire !';
    status.style.color='#4caf50';
  } else {
    status.textContent='Défaite…';
    status.style.color='#f44336';
  }
  status.style.display='';
}

// Affiche ou cache une cellule
function setCell(r,c,val,flag){
  const grid=document.getElementById('grid');
  if(flag){
    grid.children[c*COLS+r].classList.add('flagged');
    grid.children[c*COLS+r].textContent='FLAG';
  } else {
    grid.children[c*COLS+r].classList.remove('flagged');
    grid.children[c*COLS+r].textContent=getCell(val);
  }
}

// Révèle la cellule et récursivement ses voisinages vides
function reveal(r,c){
  if(r<0||r>=COLS||c<0||c>=COLS||mines.includes(r*COLS+c)) return;
  setCell(r,c,mines.includes(r*COLS+c)?10:0,false);
  if(mines.length===0) reveal(r,c); // Vérifie si on a révélé toutes les cases vides
}

// Gère les événements de la grille
const grid=document.getElementById('grid');
const cols=COLS;
for(let c=0;c<cols;c++){
  for(let r=0;r<cols;r++){
    const cell=grid.children[c*cols+r];
    cell.addEventListener('click',()=>{ setCell(r,c,cell.dataset.val,false); });
    cell.addEventListener('contextmenu',e=>{ e.preventDefault(); setCell(r,c,mines.includes(r*COLS+c)?10:0,false); });
  }
}

// Démarrage du jeu
function start(){
  initMines();
  for(let c=0;c<cols;c++){
    for(let r=0;r<cols;r++){
      cell.dataset.val=mines.includes(r*COLS+c)?10:0;
      cell.textContent=mines.includes(r*COLS+c)?'Mines':0;
      cell.classList.remove('flagged');
    }
  }
  updateStatus(false);
}

// Gestion du clic droit pour poser un drapeau
grid.addEventListener('contextmenu',e=>{
  e.preventDefault();
  const r=e.clientX/cols;
  const c=e.clientY/cols;
  if(r>=0&&r<cols&&c>=0&&c<cols&&mines.includes(r*COLS+c)){
    setCell(r,c,mines.includes(r*COLS+c)?10:0,false);
  }
});

// Démarrage initial
start();
</script>
</body>
</html>
