<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Simple Drawing App</title>
<style>
*{margin:0;padding:0;box-sizing:border-box}
body{background:#111;color:#eee;font-family:'Segoe UI',sans-serif;display:flex;justify-content:center;align-items:center;min-height:100vh}
#app{display:flex;flex-direction:column;gap:10px}
canvas{border:2px solid #333;background:#000}
#controls{display:flex;flex-direction:column;gap:5px}
label{display:flex;align-items:center;gap:5px}
input[type=range]{width:120px}
button{background:#0f3460;color:#fff;border:none;padding:8px 16px;border-radius:4px;cursor:pointer;font-size:14px}
button:hover{opacity:.85}
button:active{transform:scale(0.96)}
#downloadBtn{width:100%;background:#28a745}
#downloadBtn:hover{background:#218838}
</style>
</head>
<body>
<div id="app">
  <canvas id="drawCanvas" width="800" height="600"></canvas>
  <div id="controls">
    <label>Color:
      <input type="color" id="colorPicker" value="#0f3460">
    </label>
    <label>Size:
      <input type="range" id="sizeSlider" min="1" max="50" value="10">
      <span id="sizeVal">10</span>
    </label>
    <button id="eraseBtn">Erase</button>
    <button id="clearBtn">Clear</button>
    <button id="downloadBtn">Download PNG</button>
  </div>
</div>
<script>
const canvas = document.getElementById('drawCanvas');
const ctx = canvas.getContext('2d');
const colorPicker = document.getElementById('colorPicker');
const sizeSlider = document.getElementById('sizeSlider');
const sizeVal = document.getElementById('sizeVal');
const eraseBtn = document.getElementById('eraseBtn');
const clearBtn = document.getElementById('clearBtn');
const downloadBtn = document.getElementById('downloadBtn');

let drawing = false;
let isDown = false;
let lastX = 0;
let lastY = 0;

function resize() {
  canvas.width = canvas.clientWidth;
  canvas.height = canvas.clientHeight;
}

canvas.addEventListener('mousemove', (e) => {
  const rect = canvas.getBoundingClientRect();
  lastX = e.clientX - rect.left;
  lastY = e.clientY - rect.top;
});

canvas.addEventListener('mousedown', (e) => {
  isDown = true;
  lastX = e.clientX;
  lastY = e.clientY;
});

canvas.addEventListener('mouseup', () => {
  isDown = false;
  drawing = false;
  sizeSlider.value = 10;
  sizeVal.textContent = sizeSlider.value;
});

canvas.addEventListener('mouseleave', () => {
  isDown = false;
  drawing = false;
  sizeSlider.value = 10;
  sizeVal.textContent = sizeSlider.value;
});

canvas.addEventListener('click', () => {
  if (isDown) {
    drawing = true;
    ctx.beginPath();
    ctx.moveTo(lastX, lastY);
    ctx.lineTo(e.clientX, e.clientY);
    ctx.strokeStyle = colorPicker.value;
    ctx.lineWidth = sizeSlider.value;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.stroke();
  }
});

canvas.addEventListener('touchstart', (e) => {
  e.preventDefault();
  isDown = true;
  lastX = e.touches[0].clientX;
  lastY = e.touches[0].clientY;
});

canvas.addEventListener('touchend', (e) => {
  e.preventDefault();
  isDown = false;
  drawing = false;
  sizeSlider.value = 10;
  sizeVal.textContent = sizeSlider.value;
});

function draw() {
  if (drawing) {
    ctx.beginPath();
    ctx.moveTo(lastX, lastY);
    ctx.lineTo(e.clientX, e.clientY);
    ctx.strokeStyle = colorPicker.value;
    ctx.lineWidth = sizeSlider.value;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.stroke();
  }
}

function clear() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  drawing = false;
  sizeSlider.value = 10;
  sizeVal.textContent = sizeSlider.value;
  ctx.clearRect(0, 0, canvas.width, canvas.height);
}

function erase() {
  const isBrush = sizeSlider.value >= 10;
  ctx.globalAlpha = isBrush ? 1 : 0.2;
  ctx.strokeStyle = 'rgba(0,0,0,0)';
  ctx.lineWidth = sizeSlider.value;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  ctx.stroke();
  ctx.globalAlpha = 1;
}

function downloadPNG() {
  const link = document.createElement('a');
  link.download = 'drawing.png';
  link.href = canvas.toDataURL('image/png');
  link.click();
}

function init() {
  resize();
  colorPicker.addEventListener('input', (e) => {
    ctx.strokeStyle = e.target.value;
  });
  sizeSlider.addEventListener('input', (e) => {
    sizeVal.textContent = e.target.value;
    ctx.lineWidth = e.target.value;
  });
  eraseBtn.addEventListener('click', erase);
  clearBtn.addEventListener('click', clear);
  downloadBtn.addEventListener('click', downloadPNG);
}

init();
</script>
</body>
</html>
