.cell.flagged{background:#238636;border-radius:50%;box-shadow:0 0 12px #22c55e88}
.cell.revealed.mine{background:#ef4444;border-radius:50%;box-shadow:0 0 12px #ef444488}
.cell.flagged.mine{background:#22c55e;border-radius:50%;box-shadow:0 0 12px #22c55e88}
.cell.revealed.no-mine{background:#1e293b}
.cell.flagged.no-mine{background:#238636;border-radius:50%;box-shadow:0 0 12px #22c55e88}
.cell.revealed.flagged{background:#1e293b;box-shadow:0 0 12px #23863688}
