button:hover{opacity:.85}
#reset{background:#3b82f6;color:#fff} /* Blue */
</style>
</head>
<body>
<div id="app">
  <h1>⚡ Minesweeper</h1>
  <div id="grid"></div>
  <div id="status">Clic gauche pour révéler | Clic droit pour poser un drapeau</div>
  <div id="menu">
    <button id="reset">Rejouer</button>
  </div>
</div>
<script>
const SIZE = 9, MINES = 10;
let grid, flags, revealed, gameWon, gameLost;

function init() {
  grid = Array.from({length: SIZE}, () => Array(SIZE).fill(null));
  flags = Array.from({length: SIZE}, () => false);
  revealed = Array.from({length: SIZE}, () => false);
  gameWon = false;
  gameLost = false;
  document.getElementById('status').textContent = 'Clic gauche pour révéler | Clic droit pour poser un drapeau';
  document.getElementById('grid').innerHTML = '';
  render();
}

function render() {
  const cell = document.getElementById('grid');
  cell.innerHTML = '';
  for (let r = 0; r < SIZE; r++) {
    for (let c = 0; c < SIZE; c++) {
      const isMine = grid[r][c] === 1;
      const isFlagged = flags[r][c];
      const isRevealed = revealed[r][c];

      if (isFlagged) {
        cell.innerHTML += `<div class="cell flagged ${isMine ? 'mine' : ''}" onclick="handleClick(${r},${c})"></div>`;
        continue;
      }

      if (!isRevealed && !isFlagged) {
        const mines = countMines(r, c);
        const num = mines === 0 ? 0 : mines;
        cell.innerHTML += `<div class="cell revealed no-mine" onclick="handleClick(${r},${c})">${num}</div>`;
        continue;
      }

      if (!isRevealed && isMine) {
        cell.innerHTML += `<div class="cell mine" onclick="handleClick(${r},${c})"></div>`;
        continue;
      }

      if (isMine) {
        cell.innerHTML += `<div class="cell mine flagged" onclick="handleClick(${r},${c})"></div>`;
        continue;
      }

      if (isFlagged) {
        cell.innerHTML += `<div class="cell flagged flagged mine" onclick="handleClick(${r},${c})"></div>`;
        continue;
      }

      const mines = countMines(r, c);
      const num = mines === 0 ? 0 : mines;
      cell.innerHTML += `<div class="cell revealed no-mine" onclick="handleClick(${r},${c})">${num}</div>`;
    }
  }
}

function countMines(r, c) {
  let count = 0;
  for (let dr = -1; dr <= 1; dr++) {
    for (let dc = -1; dc <= 1; dc++) {
      const nr = r + dr, nc = c + dc;
      if (nr >= 0 && nr < SIZE && nc >= 0 && nc < SIZE) {
        if (grid[nr][nc] === 1) count++;
      }
    }
  }
  return count;
}

function handleClick(r, c) {
  if (gameWon || gameLost || revealed[r][c]) return;

  revealed[r][c] = true;

  if (grid[r][c] === 1) {
    gameLost = true;
    document.getElementById('status').textContent = '💥 Game Over! You hit a mine.';
  } else if (countMines(r, c) === 0) {
    // Recursively reveal all connected zeros
    function explore(r, c) {
      if (r < 0 || r >= SIZE || c < 0 || c >= SIZE || grid[r][c] !== 0 || revealed[r][c]) return;
      revealed[r][c] = true;
      explore(r + 1, c);
      explore(r - 1, c);
      explore(r, c + 1);
      explore(r, c - 1);
    }
    explore(r, c);
    if (countMines(r, c) === 0) {
      gameWon = true;
      document.getElementById('status').textContent = '🎉 You won! All mines are safe!';
    }
  } else {
    document.getElementById('status').textContent = `Mine at (${r},${c})`;
  }
  render();
}

function reset() {
  init();
}

// Listen events
document.getElementById('grid').addEventListener('click', (e) => {
  const cell = e.target.closest('.cell');
  if (cell) handleClick(cell.dataset.r, cell.dataset.c);
});

document.getElementById('reset').addEventListener('click', reset);
init();
</script>
</body>
</html>
