<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Simple Drawing App</title>
<style>
  *{margin:0;padding:0;box-sizing:border-box}
  canvas{background:#1a1a2e;border:2px solid #333;border-radius:6px;display:block;margin:10px auto}
  .toolbar{
    display:flex;gap:8px;justify-content:center;padding:8px;border-bottom:2px solid #333;
  }
  .toolbar button,.toolbar input[type="color"],.toolbar input[type="range"]{
    padding:4px 12px;border-radius:4px;border:1px solid #555;cursor:pointer;
  }
  .toolbar input[type="range"]{width:120px}
  #clearBtn{background:#e74c3c;color:#fff;border:none;padding:6px 16px;border-radius:4px;cursor:pointer}
  #clearBtn:hover{background:#c0392b}
  #downloadBtn{background:#2ecc71;color:#fff;border:none;padding:6px 16px;border-radius:4px;cursor:pointer}
  #downloadBtn:hover{background:#27ae60}
  #eraserBtn{background:#f1c40f;color:#000;border:none;padding:6px 16px;border-radius:4px;cursor:pointer}
  #eraserBtn:hover{background:#e67e22}
  #saveFile{background:#9b59b6;color:#fff;border:none;padding:6px 16px;border-radius:4px;cursor:pointer}
  #saveFile:hover{background:#8e44ad}
  body{font-family:'Segoe UI',system-ui,sans-serif;background:#0f1117;color:#e0e0e0;display:flex;justify-content:center;align-items:center;min-height:100vh}
</style>
</head>
<body>
<canvas id="canvas" width="800" height="600"></canvas>
<div class="toolbar">
  <button id="clearBtn">Clear</button>
  <input type="color" id="colorPicker" value="#000000">
  <input type="range" id="brushSize" min="1" max="100" value="30">
  <button id="eraserBtn">Erase</button>
  <button id="downloadBtn">Download PNG</button>
</div>
<script>
const canvas=document.getElementById('canvas'),ctx=canvas.getContext('2d');
const colorPicker=document.getElementById('colorPicker'),brushSize=document.getElementById('brushSize'),
    clearBtn=document.getElementById('clearBtn'),eraserBtn=document.getElementById('eraserBtn'),
    downloadBtn=document.getElementById('downloadBtn');

let drawing=false, brushColor='#000000', brushSize=30;

canvas.addEventListener('mousedown',e=>{
  drawing=true; let r=brushSize, x=e.offsetX, y=e.offsetY;
  ctx.beginPath(); ctx.moveTo(x,y); ctx.lineTo(x,y+r); ctx.strokeStyle=brushColor;
  ctx.lineWidth=r; ctx.lineCap='round'; ctx.lineJoin='round'; ctx.stroke();
});

canvas.addEventListener('mousemove',e=>{
  if(!drawing) return;
  let r=brushSize, x=e.offsetX, y=e.offsetY;
  ctx.clearRect(0,0,canvas.width,canvas.height);
  ctx.beginPath(); ctx.moveTo(x,y); ctx.lineTo(x,y+r); ctx.strokeStyle=brushColor;
  ctx.lineWidth=r; ctx.lineCap='round'; ctx.lineJoin='round'; ctx.stroke();
});

canvas.addEventListener('mouseup',()=>{drawing=false;});
canvas.addEventListener('mouseleave',()=>{drawing=false;});

colorPicker.oninput=e=>brushColor=e.target.value;
brushSize.oninput=e=>{brushSize=e.target.value};

eraserBtn.onclick=()=>{brushSize=0;brushColor='#ffffff';ctx.fillStyle='#ffffff';ctx.fillRect(0,0,canvas.width,canvas.height);};
clearBtn.onclick=()=>{ctx.clearRect(0,0,canvas.width,canvas.height);};
downloadBtn.onclick=()=>{drawToBlob().then(blob=>{const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='drawing.png';a.click();URL.revokeObjectURL(blob);}});

function drawToBlob(){
  const offscreen=document.createElement('canvas'),offscreen2=offscreen.getContext('2d');
  offscreen.width=canvas.width;offscreen.height=canvas.height;
  offscreen2.drawImage(canvas,0,0);
  offscreen.toBlob(blob=>{
    if(blob) URL.revokeObjectURL(blob);
  },'image/png');
}
</script>
</body>
</html>
